window.INITIAL_QUESTIONS.push(...[{"id": "QFW-20260821-COMP-CH3-001", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "001", "type": "选择题", "stem": "冯·诺依曼体系的基本结构如下图，图中标识为“①”和“②”处是（ ）。", "options": {"A": "①数据流，②控制流", "B": "①控制流，②数据流", "C": "①输入流，②输出流", "D": "①输出流，②输入流"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，冯·诺依曼计算机的基本结构包括输入设备、存储器（内存储器 和外存储器） 、运算器、控制器和输出设备。计算机的基本工作原理是“存储 程序”和“自动执行程序”， 即程序和数据都存放在存储器中，CPU 依次从 存储器中取出指令并执行。 在冯·诺依曼体系结构中： 数据流 （①） 表示数据在计算机系统中的传输路径， 包括从输入设备传输到存 储器、存储器到运算器、运算器到存储器，最终到输出设备的过程。 控制流 （②） 是指控制器根据程序的指令， 对各部件的操作进行协调和控制， 确保计算机按照指令执行。 因此，图中的 ① 代表数据流，② 代表控制流。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q001-1.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q001-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-002", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "002", "type": "选择题", "stem": "计算机能按照人们的意图自动、高速地进行操作，是因为采用了（ ）。", "options": {"A": "程序存储在内存", "B": "高性能的CPU", "C": "高级语言", "D": "机器语言"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书， 计算机能够按照人们的意图自动、 高速地进行操作， 主要依赖于 冯·诺依曼体系的“存储程序”概念， 即程序和数据都存储在内存中，CPU 通 过从内存中取指令并执行的方式来实现自动化计算。这种设计使计算机能够 连续执行指令，而无需人为干预，从而实现自动化和高速运算。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q002-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-003", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "003", "type": "选择题", "stem": "完整的计算机系统包括（ ）。", "options": {"A": "CPU和存储器", "B": "主机和实用程序", "C": "主机和外部设备", "D": "硬件系统和软件系统"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，完整的计算机系统由硬件系统和软件系统两部分组成。硬件系 统包括主机 （即 CPU、 存储器、 控制器和运算器） 和外部设备 （如输入设备、 输出设备和存储设备） ，软件系统包括操作系统、应用软件等。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q003-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-004", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "004", "type": "填空题", "stem": "没有软件的计算机称为________。", "options": {}, "verifiedAnswer": "裸机", "sourceAnswer": "裸机", "analysis": "根据考纲书，计算机系统由硬件系统和软件系统组成，硬件是计算机的物理 基础， 而软件是计算机运行的指令集合。 如果计算机仅由硬件组成， 没有软件 的支持， 那么它无法执行任何有意义的任务， 这种仅包含硬件、 没有软件的计 算机被称为“裸机”。裸机只能识别由 0 和 1 组成的机器码，用户难以直 接使用，因此必须依赖软件来完成各种计算和操作。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q004-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-005", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "005", "type": "选择题", "stem": "在计算机系统中，硬件和软件的关系最恰当的描述是（ ）。", "options": {"A": "硬件和软件完全独立，没有交集", "B": "硬件是计算机的“躯体”，软件是计算机的“灵魂”", "C": "软件可以完全替代硬件", "D": "硬件不需要软件就能独立工作"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，硬件是计算机完成各项工作的物质基础，而软件是运 行在计算机硬件上的各种程序及其相关数据， 是计算机系统的“灵魂”。“硬 件是软件建立和依托的基础， 软件是计算机系统的灵魂。 仅由硬件组成， 没有 软件的计算机称之为‘裸机’，而‘裸机’只能识别由 0、1 组成的机器代码， 用户难以直接使用。而没有硬件对于软件的物质支持，软件则无法运行”。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q005-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-006", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "006", "type": "填空题", "stem": "计算机由 5 个部分组成， 分别是________、________、________、________ 和________。", "options": {}, "verifiedAnswer": "运算器，控制器，存储器，输入设备，输出设备", "sourceAnswer": "运算器，控制器，存储器，输入设备，输出设备", "analysis": "根据考纲书， 计算机的基本组成部分包括运算器、 控制器、 存储器、 输入设备 和输出设备，这是冯·诺依曼计算机体系结构的核心内容。 ① 运算器：用于执行算术和逻辑运算。 ② 控制器：负责解释和执行指令，控制计算机各部件的协调运行。 ③ 存储器： 用于存储程序和数据， 包括内存 （RAM） 和外存 （如硬盘、U 盘 等） 。 ④ 输入设备：用于将数据和指令输入计算机，如键盘、鼠标、扫描仪等。 ⑤ 输出设备：用于将计算结果或信息输出，如显示器、打印机、音响等。 这五大组成部分共同协作， 使计算机能够接收输入、 存储数据、 进行计算并输 出结果，完成各类计算任务。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q006-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-007", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "007", "type": "填空题", "stem": "冯·诺依曼计算机的硬件系统由五大部分组成，其中整个计算机的指挥中心是 ________。", "options": {}, "verifiedAnswer": "控制器", "sourceAnswer": "控制器", "analysis": "根据考纲书，冯·诺依曼计算机的硬件系统由运算器、控制器、存储器、输入 设备和输出设备五部分组成。其中，控制器（Control Unit, CU）是整个计 算机的指挥中心，它负责从存储器中取出指令并加以分析，向计算机各部件 发出控制信号，使计算机按照程序规定的步骤自动运行。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q007-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-008", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "008", "type": "选择题", "stem": "下列不属于冯·诺依曼体系结构的是（ ）。", "options": {"A": "程序和数据以二进制形式表示", "B": "计算机由运算器、控制器、存储器、输入设备和输出设备五个部分组成", "C": "程序和数据以同等地位存储到存储器中，按地址寻访", "D": "控制器以并行的方式处理数据"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书中的描述，冯·诺依曼体系结构的计算机有三个主要特点： “① 计算机由五个基本部分组成：运算器、控制器、存储器、输入设备和输 出设备； ② 程序和数据以同等地位存放在存储器中，并要按地址寻访； ③ 程序和数据以二进制表示”。 这与选项 A、B、C 所描述的内容完全一致， 均属于冯·诺依曼体系结构的基本特征。 而 D 项“控制器以并行的方式处理数据”并不属于冯·诺依曼结构。 事实上， 控制器主要负责从内存中逐条取出指令并依次执行， 是一种顺序执行的过程， 并非并行处理。因此 D 是错误描述。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q008-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-009", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "009", "type": "选择题", "stem": "计算机的主机指的是（ ）。", "options": {"A": "计算机的主机箱", "B": "CPU和内存储器", "C": "运算器和控制器", "D": "运算器和输入输出设备"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，计算机的主机是指计算机的核心部分，通常包括CPU（中央处 理器）和内存储器。其中，CPU 由运算器和控制器组成，负责数据处理和程 序控制；内存储器用于存放正在执行的程序和数据。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q009-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q009-2.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-20261014-189"}, {"id": "QFW-20260821-COMP-CH3-010", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "010", "type": "判断题", "stem": "在微型计算机系统中，外部设备指的是安装在主机箱外面的设备。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书， 外部设备是计算机系统的重要组成部分， 用于输入数据、 输出结 果或进行数据存储，但它并不等同于“安装在主机箱外面的设备”。外部设 备包括输入设备、 输出设备和外存储器， 例如键盘、 鼠标、 显示器、 打印机、 硬盘、U 盘等。 其中， 外存储器 （如硬盘、 固态硬盘） 虽然通常安装在主机箱内部， 但仍属于 外部设备， 因为它不是计算机的核心处理单元， 而是用于数据存储。 因此， 以 “安装在主机箱外面”作为判断标准是不准确的。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q010-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-011", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "011", "type": "选择题", "stem": "下列关于计算机指令的说法中，错误的是（ ）。", "options": {"A": "指令与硬件有关", "B": "指令一般包括操作码和地址码两部分", "C": "指令是指示计算机执行某种操作的命令", "D": "指令必须经过编译后才能被计算机理解和执行"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，计算机指令是计算机执行操作的基本单位，由操作码和地址码 两部分组成。 指令直接由计算机硬件执行， 因此与硬件密切相关。 计算机执行 指令时，不需要经过编译，而是直接由 CPU 识别和执行。编译是高级语言 程序转换为机器语言的过程，而指令本身就是计算机可以直接执行的机器语 言，因此该说法错误。 综上，正确答案是 D。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q011-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-012", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "012", "type": "填空题", "stem": "计算机的工作过程实际上是快速地________的过程。", "options": {}, "verifiedAnswer": "执行指令", "sourceAnswer": "执行指令", "analysis": "根据考纲书，计算机的工作过程本质上是按照程序的指令自动、快速地执行 运算和处理数据的过程。计算机依靠存储程序和自动执行程序的机制，从存 储器中依次取出指令，并由 CPU 进行解码和执行，完成各种计算和控制任 务。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q012-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-013", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "013", "type": "填空题", "stem": "通常一条指令由________和________组成。", "options": {}, "verifiedAnswer": "操作码，地址码", "sourceAnswer": "操作码，地址码", "analysis": "根据考纲书，计算机中的指令是计算机执行操作的基本单位，通常由操作码 和地址码两部分组成。 操作码：用于指定 CPU 需要执行的操作类型，如加法、减法、存储、取数 等。 地址码：用于指示操作数的位置，即告诉 CPU 从哪里获取或存储数据。 因此，指令格式通常为：操作码+地址码。其中，操作码定义了执行的操作类 型，而地址码提供了数据存放的具体位置。 有些指令可以没有操作码，例如停机指令。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q013-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-014", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "014", "type": "选择题", "stem": "指令的有序集合称为 （ ） ， 计算机能够识别的所有指令的集合称为 （ ）。", "options": {"A": "机器语言，程序", "B": "高级语言，程序", "C": "程序，机器语言", "D": "软件，机器语言"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，计算机的指令集合指的是计算机能够直接识别和执行的一组二 进制指令，这些指令由操作码和地址码组成，统称为机器语言。指令的有序集合 称为程序", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q014-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-015", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "015", "type": "选择题", "stem": "以下（ ）不属于指令系统的指令。", "options": {"A": "数据传送指令", "B": "数据加密指令", "C": "数据处理指令", "D": "程序控制指令"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书， 计算机的指令系统是计算机 CPU 能够执行的全部指令的集合。 不同计算机的指令系统包含的指令种类和数量可能有所不同，但一般包括以 下几种类型的指令： ① 数据传送型指令：用于在存储器之间、寄存器之间，以及存储器和寄存器 之间传输数据。 ② 数据处理型指令： 用于执行算术运算 （加、 减、 乘、 除等） 和逻辑运算 （与、 或、非等） 。 ③ 程序控制型指令：用于控制程序执行流程，例如跳转、循环、调用子程序 等。 ④ 输入和输出型指令：用于实现主机与外部设备之间的数据交换，如从键盘 输入数据、将数据输出到显示器或打印机等。 ⑤ 硬件控制型指令：用于控制计算机的硬件运行，如系统初始化、关机等操 作。 这些指令类别共同构成了计算机的基本指令集，使得计算机能够执行各种任 务，从基本的数据存储与运算到复杂的程序控制和外部设备管理。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q015-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-016", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "016", "type": "填空题", "stem": "如下图所示，将不同指令的各个步骤通过多个硬件处理单元进行重叠操作， 从而实现几条指令的并行处理， 以加速程序运行过程的技术称为________技 术。", "options": {}, "verifiedAnswer": "流水线或指令流水线", "sourceAnswer": "流水线或指令流水线", "analysis": "根据考纲书，图示的技术属于流水线或指令流水线技术。流水线技术是一种 提高计算机处理速度的方法， 它通过将不同指令的各个步骤 （如取指令、分析 指令、 执行指令等） 分阶段处理， 并由多个硬件单元并行执行多个指令的不同 阶段， 从而提高 CPU 的执行效率。举例来说，当一条指令处于执行阶段时， 下一条指令可以同时进行译码，再下一条指令可以取指令，形成多条指令的 并行处理，从而提高计算机的执行效率。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q016-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q016-2.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q016-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-017", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "017", "type": "填空题", "stem": "指令流水线技术使得指令可以________执行。", "options": {}, "verifiedAnswer": "并行", "sourceAnswer": "并行", "analysis": "根据考纲书中的描述，指令流水线技术是一种提高计算机执行效率的手段， 它通过将取指、 译码、 执行等操作分成多个阶段， 使得多个指令可以在不同阶 段同时处理，从而实现“并行”执行。“指令流水线技术的基本思想是把指 令执行过程划分为若干个子过程，由多个功能部件分别完成，同时处理多个 指令的不同子过程，从而提高计算机的执行效率”。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q017-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-018", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "018", "type": "填空题", "stem": "指令的执行过程分为 3 个步骤：取指令、分析指令和________指令。", "options": {}, "verifiedAnswer": "执行", "sourceAnswer": "执行", "analysis": "根据考纲书，计算机执行指令的过程通常分为三个基本步骤： ① 取指令：CPU 从存储器（内存）中取出下一条要执行的指令，并将其存 入指令寄存器。 ② 分析指令：CPU 解析指令的操作码，确定要执行的操作类型，并获取指 令所需的操作数地址或数据。 ③ 执行指令：CPU 根据指令的功能要求，完成运算、数据传输、逻辑判断 等操作，最终得到计算结果。 因此，正确答案是：执行指令。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q018-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-019", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "019", "type": "判断题", "stem": "下图对计算机中指令的执行过程的描述是正确的。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书， 计算机的指令执行过程通常遵循取指令-分析指令-执行指令的基 本流程，并且包含程序控制机制，如判断是否为结束指令。 从图示来看，该流程正确描述了计算机指令的执行过程： ① 取指令 ② 分析指令 ③ 判断是否为结束指令： 如果是结束指令，则程序终止，进入“结束”状态。 如果不是，则执行该指令，执行完成后回到“取指令”步骤，继续下一条指 令。 这一流程符合计算机冯·诺依曼体系的基本工作原理，因此，该图对计算机指 令的执行过程描述是正确的。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q019-1.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q019-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-020", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "020", "type": "选择题", "stem": "计算机中，中央处理器 CPU 由哪两部分组成（ ）。", "options": {"A": "控制器、运算器", "B": "控制器、存储器", "C": "控制器、寄存器", "D": "寄存器、存储器"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，计算机的中央处理器（CPU）是计算机的核心部件，主要由控 制器（CU）和运算器（ALU）两部分组成。 ① 控制器：负责从存储器中取指令、分析指令，并协调各部件工作，确保程 序按顺序执行。 ② 运算器：负责执行算术运算（如加法、减法等）和逻辑运算（如与、或、 非等） 。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q020-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-021", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "021", "type": "判断题", "stem": "微型计算机中，运算器的主要功能是分析指令并译码。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，运算器（Arithmetic and Logic Unit, ALU）的主要功能是执 行算术和逻辑运算，如加、减、乘、除、与、或、非等操作，而指令的分析和 译码是控制器（Control Unit, CU）的职责。 在计算机的基本工作流程中： ① 控制器 负责取指令、分析指令，并向各部件发送控制信号。 ② 运算器 负责执行指令，即对数据进行运算，包括数值计算和逻辑判断。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q021-1.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-CH1FINAL-091"}, {"id": "QFW-20260821-COMP-CH3-022", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "022", "type": "选择题", "stem": "关于 CPU 的运算器，以下说法错误的是（ ）。", "options": {"A": "运算器的主要功能是进行算术运算和逻辑运算", "B": "运算器包括ALU和多种寄存器", "C": "运算器无法执行浮点运算", "D": "运算器中的累加器可用于存储运算中间结果"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书中的描述，运算器的主要功能是“执行数值数据的算术加、减、 乘、 除等运算， 执行逻辑数据的与、 或、 非等逻辑运算”， 并且“现在的运算 器内部还集成了浮点运算部件（Floating Point Unit, FPU） ，用来提高浮点 运算速度”。这说明运算器是可以执行浮点运算的，C 项“运算器无法执行 浮点运算”是错误的描述。 其余选项： A、正确，明确了运算器的基本功能； B、正确，运算器确实包括算术逻辑单元(ALU)和各种寄存器； D、 正确，“累加器是一个具有特殊功能的寄存器， 用来传输并临时存储待运 算的一个操作数、ALU 运算的中间结果和其他数据”。 因此，答案为 C", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q022-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-023", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "023", "type": "选择题", "stem": "下列关于 CPU 控制器的描述中，不正确的是（ ）。", "options": {"A": "控制器负责从内存中取指令和分析指令", "B": "控制器包括程序计数器、指令寄存器和指令译码器", "C": "控制器无法向其他部件发出控制信号", "D": "指令译码器用于识别和分析指令"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书中的描述，控制器是“计算机的指挥中枢”，其作用是“用于控 制计算机各个部件按照指令的功能要求协同工作”，具体功能包括“从内存 取指令、分析指令和向其他部件发出控制信号”。因此，C 项“控制器无法 向其他部件发出控制信号”显然错误。 其他选项： A、正确，属于控制器的基本功能； B、正确，控制器的主要部件包括“程序计数器(PC)、指令寄存器(IR)、指令 译码器(ID)”等； D、 正确，“指令译码器”用于“识别指令的功能， 分析指令的操作要求”。 因此，答案为 C", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q023-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-024", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "024", "type": "选择题", "stem": "微型计算机中，能实现算术运算、逻辑运算及全机控制的部件是（ ）。", "options": {"A": "运算器", "B": "控制器", "C": "内存储器", "D": "微处理器"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书中的描述， “控制器与运算器共同组成了中央处理器（ Central Processing Unit, CPU ） ， 是 计 算 机 的 核 心 部 分” ，而 “ 微 处 理 器 （Microprocessor） 就是将中央处理器 （即运算器和控制器） 集成在一个芯 片上，它能完成算术运算、逻辑运算及全机控制”。 因此，D 项“微处理器”是唯一包含算术运算、逻辑运算以及全机控制全部 功能的部件。 其他选项： A、运算器只能完成算术和逻辑运算； B、控制器负责协调和控制，但不执行运算； C、内存储器主要负责存储数据和程序，不具备计算或控制功能。 因此，答案为 D", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q024-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q024-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-025", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "025", "type": "选择题", "stem": "一般来说，CPU 的（ ）越高，运算速度也就越快。", "options": {"A": "位数", "B": "主频", "C": "带宽", "D": "字长"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，CPU 的主频（Clock Speed） 指的是 CPU 每秒钟执行的时钟 频率， 通常以 MHz（百万次/秒） 或 GHz（十亿次/秒） 为单位。 一般来说， 主频越高，CPU 在单位时间内可以执行的指令就越多， 因此运算速度也就越 快。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q025-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-026", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "026", "type": "选择题", "stem": "CPU 的主频是指 CPU 的（ ）。", "options": {"A": "无线电频率", "B": "电压频率", "C": "时钟频率", "D": "电流频率"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，CPU 的主频（Clock Speed） 指的是 CPU 每秒钟执行的时钟 频率，通常以 MHz（百万次/秒）或 GHz（十亿次/秒）为单位。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q026-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q026-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-027", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "027", "type": "判断题", "stem": "可通过设置高速缓冲存储器（Cache）来增加计算机内存的容量。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，“为了解决对存储器要求容量大、 速度快、 成本低三者 之间的矛盾， 目前通常采用多级存储器体系结构， 即使用高速缓冲存储器、 主 存储器和外存储器。这时内存包括主存与高速缓存两部分，高速缓存存放当 前使用最频繁的指令和数据并实现高速存取”。 由此可见， 高速缓冲存储器 （Cache） 的作用是提高访问速度， 并不能增加计 算机内存的容量，它只是存储热点数据的临时区域，不属于主存容量的一部 分。 因此，答案为：错", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q027-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-028", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "028", "type": "选择题", "stem": "Cache 可以提高计算机的性能，这是因为（ ）。", "options": {"A": "提高了CPU的倍频", "B": "提高了CPU的主频", "C": "提高了RAM的容量", "D": "缩短了CPU访问数据的时间"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，Cache（高速缓存） 的主要作用是缩短 CPU 访问数据的时间， 从而提高计算机的整体性能。Cache 介于 CPU 和主存 （RAM） 之间， 存储 最近使用或即将使用的数据，使 CPU 在需要数据时可以更快地从 Cache 获取，而不必等待较慢的 RAM 访问。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q028-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-029", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "029", "type": "选择题", "stem": "CPU 中的 L1、L2 和 L3 Cache 的主要区别在于（ ）。", "options": {"A": "它们的容量大小不同，L1 Cache最大，L3 Cache最小", "B": "它们的运行频率不同，L1 Cache最慢，L3 Cache最快", "C": "L1 Cache和L2 Cache是每个核心独立的，而L3 Cache是多个核心共享 的", "D": "只有L3 Cache可以减少CPU从内存读取数据的等待时间"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，CPU 中的 L1、L2 和 L3 Cache 主要用于加速数据访问，它 们之间的主要区别在于层级结构和共享方式： ① L1 Cache（一级缓存） ：速度最快，容量最小（通常 32KB - 128KB） ，每 个 CPU 核心独立拥有。 ② L2 Cache（二级缓存） ：比 L1 稍慢，容量更大（通常 256KB - 1MB）， 通常每个核心独立拥有，但在部分架构中可以被多个核心共享。 ③ L3 Cache（三级缓存） ： 速度比 L2 缓慢， 但容量更大 （通常 2MB - 64MB）， 多个核心共享，用于进一步减少 CPU 访问内存的时间。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q029-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q029-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-030", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "030", "type": "判断题", "stem": "与 CPU 封装在一起的 cache 可看作主存的延伸， 与主存统一编址，接受 CPU 的访问，但速度比主存快。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，CPU 内部封装的 Cache（高速缓存）并不属于主存（RAM） 的一部分，而是独立的存储单元，它与主存不统一编址，且通常由 CPU 内 部控制，不直接对外部设备开放访问。Cache 的作用是加速数据访问，减少 CPU 直接访问主存的延迟，但它并不等同于主存的扩展。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q030-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-031", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "031", "type": "选择题", "stem": "在计算机中， 作为一个整体参与运算、 处理和传送的一串二进制数称为 （ ）， 其位数称为（ ）。", "options": {"A": "字，字长", "B": "字长，字", "C": "字节，字长", "D": "字长，字节"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，计算机中的“字”是指作为一个整体参与运算、处理和传送的 一串二进制数，而该串二进制数的位数被称为字长。 ① 字：计算机处理数据时， CPU 一次存取、加工和传送的数据单位称为 “字”。 ② 字长： 计算机一次能处理的二进制位数， 即 CPU 一次操作的位宽， 如 8 位、16 位、32 位或 64 位。 字长越长，CPU 的精度越高， 计算能力也越强。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q031-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q031-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-032", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "032", "type": "选择题", "stem": "CPU 的字长（ ）通用寄存器的位数。", "options": {"A": "小于", "B": "等于", "C": "大于", "D": "不等于"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，CPU 的字长通常指的是 CPU 一次能处理的二进制数据位数， 而通用寄存器的位数通常与 CPU 的字长相同，因为通用寄存器用于存储 CPU 处理的数据和指令操作数。 如果 CPU 的字长是 32 位， 那么其通用寄 存器的位数通常也是 32 位；如果是 64 位 CPU，则寄存器的位数也是 64 位。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q032-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-033", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "033", "type": "选择题", "stem": "CPU 的字长决定了（ ）。", "options": {"A": "CPU的主频", "B": "CPU的能耗", "C": "CPU处理数据的精度", "D": "CPU的功能"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，CPU 的字长指的是 CPU 一次能够处理的二进制数据的位数， 通常以 8 位、16 位、32 位或 64 位表示。字长越长，CPU 在计算过程中 能处理的数据范围越大，数据精度也越高。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q033-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-034", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "034", "type": "选择题", "stem": "“64 位微机”中的 64 位指的是（ ）。", "options": {"A": "CPU型号", "B": "存储单位", "C": "内存容量", "D": "机器字长"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，“64 位微机”中的 64 位 指的是 CPU 的字长，即 CPU 一 次能处理的二进制数据的位数。 64 位 CPU 能够一次处理 64 位二进制数 据，具有更高的数据吞吐能力，同时也支持更大的内存寻址空间（可寻址 16EB 的内存） 。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q034-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-035", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "035", "type": "填空题", "stem": "目前手机、个人电脑、服务器等设备使用的________广泛采用多核技术，对 提高处理速度具有显著作用。", "options": {}, "verifiedAnswer": "CPU", "sourceAnswer": "CPU", "analysis": "考纲书上的原话，记住结论即可。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q035-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-036", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "036", "type": "判断题", "stem": "睿频技术允许 CPU 在重任务时提高主频，而在轻任务时降低主频以节能。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，睿频技术（Turbo Boost） 是现代 CPU 采用的一种动态频率 调节技术，它能够根据任务的负载情况自动调整 CPU 的主频，以实现性能 和功耗的平衡。 ① 重任务时提高主频：当 CPU 运行高强度任务（如游戏、视频编辑、大规 模计算）时，睿频技术会自动提升 CPU 频率，以提高计算速度。 ② 轻任务时降低主频：当 CPU 处于低负载状态（如浏览网页、编辑文档） 时，睿频技术会降低 CPU 频率，以减少功耗并降低发热量，从而延长电池 续航（对移动设备尤其重要） 。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q036-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-037", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "037", "type": "判断题", "stem": "QPI 总线的带宽越高，意味着 CPU 的数据处理能力越强。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，QPI（Quick Path Interconnect）总线 是 Intel 处理器架构 中的高速点对点互连技术，用于 CPU 与内存、I/O 设备以及其他 CPU 之 间的数据传输。QPI 总线的带宽越高，意味着数据在 CPU 和其他组件之间 的传输速度更快，从而提高 CPU 的数据处理能力。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q037-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-038", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "038", "type": "判断题", "stem": "多线程机制能减少 CPU 的闲置时间，提高 CPU 的运行效率。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书， 多线程机制 （Multithreading） 是 CPU 通过同时处理多个线 程 来提高计算效率的一种技术。 多线程机制的核心目标是减少 CPU 的空闲 时间，充分利用计算资源，从而提高 CPU 的运行效率。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q038-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-039", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "039", "type": "选择题", "stem": "下列选项中，不属于智能处理器特征的是（ ）。", "options": {"A": "采用睿频加速技术，按负载提升主频，高效节能", "B": "采用超线程技术，提升CPU的并行处理能力", "C": "集成高清显卡，大幅提升3D性能", "D": "集成专业声卡，大幅提升声音质量"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，智能处理器 主要具备以下特征： A、睿频加速技术（A 选项） ： 根据 CPU 负载动态调整主频，在高负载时提升性能，低负载时降低功耗， 提高能效。 B、超线程技术（B 选项） ： 让 CPU 的每个物理核心能够同时运行多个线程，提高 CPU 的并行计算能 力，提升处理效率。 C、集成高清显卡（C 选项） ： 现代 CPU 逐渐集成 GPU（图形处理单元） ， 以提高 3D 渲染和多媒体处理 能力，如 Intel 核显和 AMD APU。 声卡（D 选项）一般集成主板上，并不会集成在 CPU 内部。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q039-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-040", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "040", "type": "多选题", "stem": "（多选）微型计算机系统处理大量数据信息的速度取决于（ ）。", "options": {"A": "CPU的时钟频率", "B": "内存的容量和读写速度", "C": "显示器的分辨率和刷新频率", "D": "硬盘的容量和读写速度"}, "verifiedAnswer": "ABD", "sourceAnswer": "ABD", "analysis": "根据考纲书中的描述，微型计算机系统的运行效率与多种硬件参数有关： A、CPU 是计算机的核心部件，其“运算器和控制器共同组成了中央处理器 （CPU）”，而 CPU 的“运算速度”直接影响计算任务的处理速度，因此 CPU 的时钟频率越高，执行指令的速度也越快。 B、内存储器的“容量”决定了可同时存放的数据量， “存取速度”则影响 CPU 读取数据的效率，“内存的特点是存取速度快，但容量小、价格贵”， 因此内存的容量和读写速度对处理大量数据起关键作用。 D、 硬盘属于外存储器， 虽然存取速度较慢， 但其容量大， 通常用于存放大量 程序和数据，因此硬盘的容量和读写速度也会影响到系统的数据处理能力， 特别是在数据交换频繁的场景中。 C、 显示器的分辨率和刷新频率主要关系到图像显示效果， 与系统处理数据的 “速度”无直接关系，不能作为决定因素。 因此，答案为：ABD", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q040-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-041", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "041", "type": "多选题", "stem": "（多选）以下能够影响到计算机运行复杂计算问题求解程序速度的因素包括 （ ）。", "options": {"A": "CPU主频的高低", "B": "主内存容量的大小", "C": "硬盘接口速度的高低", "D": "高速缓存（Cache）的容量大小和命中率高低"}, "verifiedAnswer": "ABD", "sourceAnswer": "ABD", "analysis": "根据考纲书中的描述，影响计算机运行复杂计算问题求解程序速度的主要因 素包括以下几方面： A、CPU 主频的高低直接影响计算速度。CPU 是“计算机的核心部分”，负 责指令的执行和数据的处理，主频越高，指令执行越快。 B、 主内存容量的大小影响能否一次性装载更多数据和程序。 内存是“用来存 放要执行的程序和数据”的，容量越大，计算机运行大程序的效率越高。 D、高速缓存 （Cache）的容量和命中率是关键性能参数。考纲书指出“高速 缓存存放当前使用最频繁的指令和数据并实现高速存取”，其容量和命中率 直接关系到 CPU 访存效率，是影响运行速度的重要因素。 C、 硬盘接口速度的高低影响的是数据的存取时间， 但在执行程序 （特别是计 算密集型程序）时，主要是在内存和CPU 之间进行操作，硬盘接口速度影响 相对较小，因此不是主要因素。 因此，答案为：ABD", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q041-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q041-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-042", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "042", "type": "多选题", "stem": "（多选）计算机上安装了主时钟频率很高，运算能力非常强的CPU，但计算 机运行 3DMAX 软件进行三维图像处理的速度却并不快， 原因可能包括 （ ）。", "options": {"A": "显示器分辨率偏低", "B": "显示适配器缓存容量偏小", "C": "光盘驱动器读写速度慢", "D": "硬盘驱动器读写速度慢", "E": "内存容量偏小"}, "verifiedAnswer": "BE", "sourceAnswer": "BE", "analysis": "根据考纲书中的描述和相关硬件知识， 运行3DMAX 等三维图像处理软件时， 需要较强的图形处理能力和系统资源支持： B、显示适配器（显卡）是图形处理的关键部件，其缓存容量（显存）影响图 像渲染的速度和质量，显存偏小会导致图像处理能力受限，拖慢运行速度。 E、 内存容量决定了程序运行时可用的数据缓冲和暂存空间， 考纲书指出“内 存用来存放要执行的程序和数据”，容量过小时系统可能频繁与硬盘交换数 据，严重影响效率。 其余选项分析如下： A、显示器分辨率偏低只影响画面清晰度，与软件运行速度无直接关系； C、光盘驱动器主要用于读取光盘数据，而 3DMAX 运行时并不依赖光盘； D、 硬盘读写速度虽会影响数据加载， 但对实时图形处理影响较小， 关键在内 存和显卡。 因此，答案为：BE", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q042-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-043", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "043", "type": "选择题", "stem": "下列不属于国产芯片的是（ ）。", "options": {"A": "麒麟", "B": "酷睿", "C": "龙芯", "D": "申威"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书， 国产芯片 是指由中国自主研发和生产的 CPU 芯片， 代表着中 国在芯片领域的自主创新能力。 国产芯片： A、麒麟：华为海思研发的 ARM 架构处理器，广泛应用于华为手机。 C、 龙芯 （Loongson） ： 中国科学院计算技术研究所研制的自主指令集 CPU， 主要用于国产 PC 和服务器。 D、申威：用于中国国产超级计算机“神威·太湖之光”，采用自主研发的架 构。 B、酷睿（Core）是 Intel（英特尔）公司研发的 x86 架构处理器，广泛应 用于全球 PC 和服务器市场，因此不属于国产芯片。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q043-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-044", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "044", "type": "选择题", "stem": "关于龙芯 CPU 的描述，以下哪项是错误的（ ）。", "options": {"A": "龙芯CPU是基于RISC架构", "B": "龙芯CPU主要应用于个人计算机", "C": "龙芯CPU具有自主知识产权", "D": "龙芯处理器采用简单指令集"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，龙芯（Loongson）CPU 是中国自主研发的处理器，具有自主 知识产权， 并基于 RISC（精简指令集计算机） 架构。 虽然龙芯 CPU 可以用 于个人计算机， 但它的主要应用领域包括超级计算机、国产服务器、 嵌入式系 统和工业控制等，并非主要针对个人 PC 市场。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q044-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-045", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "045", "type": "填空题", "stem": "内存是 CPU 能够________访问的存储器， 用于存放正在运行的程序和数据。", "options": {}, "verifiedAnswer": "直接", "sourceAnswer": "直接", "analysis": "根据考纲书，内存（RAM，随机存取存储器）是 CPU 能够直接访问的存储 器， 用于存放正在运行的程序和数据。 由于内存的访问速度比外存 （如硬盘） 快得多，CPU 直接从内存中读取指令和数据，以提高计算效率。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q045-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-046", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "046", "type": "判断题", "stem": "程序必须调入内存运行。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，计算机采用冯·诺依曼体系结构，其中程序和数据必须存储在内 存中，CPU 才能直接访问。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q046-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-047", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "047", "type": "判断题", "stem": "打开一个 Word 文档，是指把该文档从磁盘调入内存，并在窗口的工作区显 示其内容。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，计算机采用冯·诺依曼体系结构，其中程序和数据必须存 储在内存中，CPU 才能直接访问。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q047-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-048", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "048", "type": "判断题", "stem": "在微型计算机中，CPU 对内存的操作有“读”和“写”，“读”操作是指将 内存单元中的内容读入到 CPU 的内部，“写”操作则是 CPU 将信息传送到 内存单元并保存起来。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书中的描述，“对存储器的基本操作是按照指定位置存入或取出二 进制信息”，“从存储单元读取其内容后， 该单元仍然保存着原来的内容， 可 以重复读取； 把数据写入存储单元， 该单元的原有内容就被覆盖”。 这正是所 谓“读”和“写”的操作定义：“读”是将内存数据传送给 CPU，“写”是 将 CPU 的数据保存到内存。 因此，答案为：对", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q048-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-049", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "049", "type": "选择题", "stem": "以下描述（ ）不正确。", "options": {"A": "内存与外存的区别在于内存是临时性的，而外存是永久性的", "B": "内存与外存的区别在于外存是临时性的，而内存是永久性的", "C": "平时说得内存是指RAM", "D": "从输入设备输入的数据直接存放在内存"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，内存是计算机中“用来存放要执行的程序和数据”的 临时存储部件， 属于易失性存储器， 断电后数据会消失； 而“外存用来长期存 放程序和数据”，具有永久性存储的特点。因此，B 项“外存是临时性的， 而内存是永久性的”是错误的。 其它选项： A、正确，内存临时、外存长期； C、正确，“通常所说的内存主要指 RAM”； D、正确，从输入设备输入的数据“转换成计算机可以识别的形式(二进制)存 放到内存中”。 因此，答案为：B", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q049-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-050", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "050", "type": "选择题", "stem": "内存储器是 CPU 能直接访问的存储器，下列哪一个不属于内存储器（ ）。", "options": {"A": "随机访问存储器", "B": "只读存储器", "C": "高速缓冲存储器", "D": "优盘存储器"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，内存储器是 CPU 能直接访问的存储器，用于存储正在运行的 程序和数据，常见的内存储器包括： A、 随机访问存储器 （RAM） ： 属于内存，CPU 可直接访问， 存储临时数据。 B、只读存储器（ROM） ：属于内存，存储固化的系统程序，如 BIOS。 C、 高速缓冲存储器 （Cache） ： 属于 CPU 内部的缓存， 用于加速数据访问。 D、优盘存储器（U 盘）属于外部存储设备（外存） ，数据需要先从 U 盘读 入内存，CPU 才能访问，因此不属于内存储器。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q050-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-051", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "051", "type": "选择题", "stem": "下列存储器中， （ ）的特点是只能读出原有内容，不能由用户再写入新内 容。", "options": {"A": "RAM", "B": "ROM", "C": "DRAM", "D": "SRAM"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，只读存储器（ROM，Read-Only Memory） 是一种只能读出 原有内容，而不能由用户写入新内容的存储器。ROM 在出厂时就已经写入了 固定的程序或数据， 用户无法随意修改， 主要用于存储 BIOS、 固件等系统级 程序。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q051-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-052", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "052", "type": "选择题", "stem": "引导系统开机自检的程序存放在（ ）。", "options": {"A": "硬盘", "B": "ROM", "C": "内存", "D": "磁盘"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，引导系统开机自检（POST，Power-On Self Test）的程序存放 在 ROM（只读存储器）中。ROM 中存储的 BIOS（基本输入输出系统）负 责在计算机开机时执行硬件自检 （POST） ， 并引导操作系统启动。 由于 ROM 具有断电不丢失数据的特性，因此适合存放开机时必须执行的固件程序。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q052-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q052-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-053", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "053", "type": "选择题", "stem": "微型计算机系统中的内存条指的是（ ）。", "options": {"A": "ROM", "B": "RAM", "C": "CD-ROM", "D": "CMOS"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，内存条指的是 RAM（随机存取存储器） ， RAM 中用于存放正 在运行的程序和数据，CPU 可以直接访问 RAM。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q053-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-054", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "054", "type": "选择题", "stem": "以下安装在计算机内部主板插槽上的部件是（ ）。", "options": {"A": "静态内存", "B": "动态内存", "C": "高速缓存", "D": "FLASH缓存"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，内存条指的是 RAM（随机存取存储器） ， RAM 中用于 存放正在运行的程序和数据，CPU 可以直接访问 RAM", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q054-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-055", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "055", "type": "填空题", "stem": "RAM 主要的性能指标有两个： ________和________。", "options": {}, "verifiedAnswer": "存储容量，存取速度", "sourceAnswer": "存储容量，存取速度", "analysis": "根据考纲书，RAM 的性能主要取决于两个关键指标： ① 存储容量： 指 RAM 可以存储的数据总量， 通常以 GB 为单位， 如 8GB、 16GB、32GB。存储容量越大，系统可以运行的程序和数据就越多，性能更 好。 ② 存取速度：指 CPU 访问 RAM 读取或写入数据的速度，通常由内存频 率（MHz）和延迟决定，例如 DDR4 3200MHz、DDR5 4800MHz。存取速 度越快，数据交换效率越高，系统运行更流畅。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q055-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-056", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "056", "type": "选择题", "stem": "微型计算机内存容量的基本单位是（ ）。", "options": {"A": "字符", "B": "字节", "C": "二进制位", "D": "扇区"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，微型计算机内存容量的基本单位是“字节”（Byte，B） 。在计 算机存储体系中，字节（B）是最基本的数据存储单位，通常用于衡量内存、 硬盘等存储设备的容量。 其它选项： A、字符：字符是数据的一种表示方式，而不是存储容量的基本单位； C、二进制位 （bit） ：虽然计算机数据存储的最小单位是 bit（位） ， 但内存容 量通常以 字节（Byte） 作为计算单位，1 字节 = 8 位； D、 扇区： 扇区是硬盘等存储设备上的数据存储单位， 通常 1 扇区 = 512 字 节。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q056-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-057", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "057", "type": "填空题", "stem": "为了能存取内存的数据，每个内存单元必须有一个唯一的编号，称为 ________。", "options": {}, "verifiedAnswer": "地址或内存地址", "sourceAnswer": "地址或内存地址", "analysis": "根据考纲书， 为了能存取内存的数据， 每个内存单元必须有一个唯一的编号， 称为地址或内存地址。 地址是计算机存储器中每个存储单元的唯一标识，CPU 通过内存地址来读取或写入数据。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q057-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q057-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-058", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "058", "type": "填空题", "stem": "在程序运行时， 可以根据________直接访问随机文件结构中的某一特定记录。", "options": {}, "verifiedAnswer": "地址或主键", "sourceAnswer": "地址或主键", "analysis": "根据考纲书， 为了能存取内存的数据， 每个内存单元必须有一个唯一的 编号，称为地址或内存地址。地址是计算机存储器中每个存储单元的唯一标 识，CPU 通过内存地址来读取或写入数据。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q058-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-059", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "059", "type": "选择题", "stem": "为了解决用户要求存储容量大、速度快和成本低之间的矛盾，目前计算机采 用高速缓冲存储器（cache） 、内存储器和外存储器的体系结构，该体系结构 是（ ）。", "options": {"A": "多级存储结构", "B": "固态硬盘阵列", "C": "机械硬盘阵列", "D": "多级流水线存储结构"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书， 为了平衡存储容量、 访问速度和成本之间的矛盾， 计算机采用多 级存储结构， 即通过高速缓冲存储器 （Cache） 、 内存储器 （RAM） 和外存储 器（硬盘、固态硬盘等）组成的层次化存储系统。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q059-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-060", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "060", "type": "选择题", "stem": "计算机的多级存储器体系结构中，Cache 的作用是（ ）。", "options": {"A": "长期存储数据", "B": "存放当前使用最频繁的指令和数据", "C": "存放启动程序", "D": "作为CPU的主要存储单元"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书， 在计算机的多级存储器体系结构中，Cache（高速缓存） 主要用 于存放当前使用最频繁的指令和数据，以提高 CPU 访问速度，减少访问内 存（RAM）的时间。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q060-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q060-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-061", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "061", "type": "判断题", "stem": "计算机的外存储器比内存储器存取速度快。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，“内存的特点是存取速度快， 但容量小、 价格贵； 外存 的特点是容量大、价格低，但是存取速度慢”。这表明外存的速度远低于内 存，不能说外存比内存快。 因此，题目中的说法是错误的。 答案为：错", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q061-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-062", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "062", "type": "选择题", "stem": "在微型计算机系统常用的存储器中，读写速度最快的是（ ）。", "options": {"A": "硬盘", "B": "U盘", "C": "光盘", "D": "内存"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书， 在微型计算机系统常用的存储器中， 内存 （RAM） 的读写速度 最快，远远快于硬盘、U 盘和光盘。 存储器读写速度从快到慢： ① CPU 寄存器（最快，纳秒级） ② Cache（高速缓存） （纳秒级，比 RAM 快） ③ 内存（RAM） （微秒级，远快于硬盘和外部存储设备） ④ 固态硬盘（SSD） （比机械硬盘快，但比 RAM 慢） ⑤ 机械硬盘（HDD） （毫秒级） ⑥ U 盘、光盘等外部存储设备（速度最慢）", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q062-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-063", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "063", "type": "选择题", "stem": "计算机机存储体系由多级存储部件构成， 下列部件存储速度最快的是（ ）。", "options": {"A": "硬盘", "B": "寄存器", "C": "RAM", "D": "cache"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书， 在微型计算机系统常用的存储器中， 内存 （RAM） 的读 写速度最快，远远快于硬盘、U 盘和光盘。 存储器读写速度从快到慢： ① CPU 寄存器（最快，纳秒级） ② Cache（高速缓存） （纳秒级，比 RAM 快） ③ 内存（RAM） （微秒级，远快于硬盘和外部存储设备） ④ 固态硬盘（SSD） （比机械硬盘快，但比 RAM 慢） ⑤ 机械硬盘（HDD） （毫秒级） ⑥ U 盘、光盘等外部存储设备（速度最慢）", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q063-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-064", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "064", "type": "判断题", "stem": "计算机处理的文件和数据存入磁盘后能被 CPU 直接访问。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，计算机的外存（如磁盘）是“用来长期存放程序和数 据”的，但“外存一般只与内存进行数据交换”，CPU 不能直接访问外存， 而是“计算机可以直接从内存储器中存取信息”。因此，从磁盘读取的数据 必须先加载到内存，CPU 才能处理。 所以，文件和数据存入磁盘后不能被 CPU 直接访问。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q064-1.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-CH1FINAL-098"}, {"id": "QFW-20260821-COMP-CH3-065", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "065", "type": "选择题", "stem": "磁盘驱动器属于（ ）设备。", "options": {"A": "输入", "B": "输出", "C": "输入和输出", "D": "以上均不是"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书中的描述， 任何一种存储器都包含存储介质和存储设备。 其中，磁 盘驱动器是一种存储设备， 它在使用过程中既能将数据从磁盘读取到内存 （输 入操作） ， 也能将数据从内存写入磁盘 （输出操作） ， 因此它兼具输入和输出功 能，属于输入/输出（I/O）设备的一种。 因此，答案为：C", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q065-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q065-2.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-20261014-192"}, {"id": "QFW-20260821-COMP-CH3-066", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "066", "type": "选择题", "stem": "下列存储设备中，存取速度最快的是（ ）。", "options": {"A": "DVD-RW", "B": "FD", "C": "HD", "D": "SSD"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，存储设备的存取速度由其存储介质和读写技术决定。 DVD-RW（A）是一种光存储介质，采用激光读取，存取速度较慢。 FD（B，即软盘）采用磁介质存储，数据传输速率极低，存取速度最慢。 HD（C，即传统机械硬盘）使用磁盘旋转和磁头读写，虽然比软盘快，但仍 远逊于固态硬盘。 SSD（D，即固态硬盘）采用闪存技术，没有机械部件，具有更快的存取速度 和数据吞吐能力，是四者中存取速度最快的存储设备。外存中SSD 最快，记 住这个结论。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q066-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-067", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "067", "type": "选择题", "stem": "和机械硬盘相比，固态硬盘的主要优点是（ ）。", "options": {"A": "容量大", "B": "读写速度快", "C": "价格便宜", "D": "使用寿命长"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书， 固态硬盘 （SSD） 采用闪存技术， 没有机械部件， 因此比传统机 械硬盘（HDD）具有更快的读写速度，这是其主要优势。容量、价格和使用 寿命上，SSD 都比不上传统的机械硬盘。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q067-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q067-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-068", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "068", "type": "多选题", "stem": "（多选）允许随意写入数据文件，并且在断电后不会丢失信息的存储媒体有 （ ）。", "options": {"A": "U盘", "B": "硬盘", "C": "光盘", "D": "键盘"}, "verifiedAnswer": "AB", "sourceAnswer": "AB", "analysis": "根据考纲书中的描述，外存储器包括硬盘、光盘、U 盘等，它们的共同特征 是“容量大、 价格低， 但是存取速度慢”， 并且可以“长期存放程序和数据”。 其中： A、U 盘是一种闪存类型的外存， 可以随意写入数据， 并且断电后信息不丢失， 属于非易失性存储器。 B、 硬盘也是一种典型的非易失性外部存储设备， 可以反复读写， 断电后数据 仍然保留。 C、光盘虽然也属于外存，但并不都支持随意写入。常见的CD-ROM 是只读 的，CD-R 是一次写入， 而CD-RW 才支持多次写入， 但速度和灵活性不如U 盘和硬盘。 D、键盘属于输入设备，不具备数据存储功能。 因此，答案为：AB", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q068-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-069", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "069", "type": "选择题", "stem": "光盘驱动器通过激光束来读取光盘上的数据时，光学头与光盘（ ）。", "options": {"A": "直接接触", "B": "不直接接触", "C": "播放VCD时接触", "D": "有时接触有时不接触"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，光盘驱动器在读取光盘数据时，光学头通过激光束照射光盘表 面的凹坑和反射区域来读取数据，而不会与光盘直接接触。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q069-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q069-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-070", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "070", "type": "选择题", "stem": "衡量一个光驱性能的主要指标是（ ）。", "options": {"A": "光盘的容量", "B": "盘片的类型", "C": "读取数据的速率", "D": "使用寿命"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书中的描述，光驱作为外部存储设备的一种，其性能主要体现在读 取数据的能力上。 在日常使用中， 用户最关心的是光驱读取光盘内容的速度， 因此“读取数据的速率”是衡量光驱性能的最主要指标。速率越高，数据传 输效率越快，光盘使用体验越好。 A、光盘容量是光盘本身的属性，不属于光驱性能的衡量标准； B、盘片类型决定是否兼容，但不是衡量性能的主要指标； D、使用寿命虽影响长期使用，但非性能主要指标。 因此，答案为：C", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q070-1.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-20261014-208"}, {"id": "QFW-20260821-COMP-CH3-071", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "071", "type": "填空题", "stem": "在计算机上用于衡量光盘驱动器传输数据速率的指标称为________。", "options": {}, "verifiedAnswer": "倍速", "sourceAnswer": "倍速", "analysis": "根据考纲书，衡量光盘驱动器传输数据速率的指标称为倍速（X）。 CD 的1X = 150KB/s，DVD 的1X = 1350KB/s。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q071-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-072", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "072", "type": "填空题", "stem": "CD-ROM 光驱的 1 倍速为 ________KBps ， DVD 光驱的 1 倍速为 ________KBps。", "options": {}, "verifiedAnswer": "150，1350", "sourceAnswer": "150，1350", "analysis": "根据考纲书，衡量光盘驱动器传输数据速率的指标称为倍速（X）。 CD 的1X = 150KB/s，DVD 的1X = 1350KB/s。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q072-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q072-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-073", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "073", "type": "填空题", "stem": "CD-ROM 光盘 的 容量通常为 ________MB， DVD 光盘的容量一般为 ________GB。", "options": {}, "verifiedAnswer": "650，4.7", "sourceAnswer": "650，4.7", "analysis": "根据考纲书中的描述，常见的 CD-ROM 光盘容量通常为 650MB 左右，而 DVD 光盘因数据密度更高， 标准容量一般为 4.7GB， 这是单面单层DVD 的 容量。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q073-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-074", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "23 输入设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "074", "type": "判断题", "stem": "输入设备接受用户输入的原始数据和程序，并将它们转换成计算机可以识别 的形式； 输出设备用于将计算机处理的结果转变为用户可接受的形式。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，输入设备的主要功能是接受用户输入的原始数据和程序，并将 其转换为计算机可以识别的二进制数据存入内存，例如键盘、鼠标、扫描仪 等。 输出设备的功能是将计算机处理的结果转换为用户可理解的形式并输出，例 如显示器、打印机、音响等。 因此，题干的描述是正确的。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q074-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-075", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "23 输入设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "075", "type": "填空题", "stem": "常用的输入设备有________、鼠标、触摸屏、扫描仪、话筒等。", "options": {}, "verifiedAnswer": "键盘", "sourceAnswer": "键盘", "analysis": "见上题。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q075-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-076", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "23 输入设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "076", "type": "判断题", "stem": "在多媒体扩展设备中，触摸屏是一种坐标定位装置，属于输出设备。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书， 触摸屏一般特指其作为坐标定位装置的 “外屏”， 属于输入设备， 而不是输出设备。它通过手指或触控笔的触摸来接收用户输入，将触摸位置 转换为计算机可以识别的坐标信息，从而进行交互。 如果题目中的“触摸屏”包含了用于显示内容的“内屏” ，那么内屏属于输出 设备，而外屏属于输入设备。从这个角度上来说，可以说包含了“内屏”和 “外屏”的触摸屏（显示触摸屏）既属于输入设备，又属于输出设备。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q076-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-077", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "077", "type": "填空题", "stem": "常用的输出设备是显示器、________、绘图仪、音响等。", "options": {}, "verifiedAnswer": "打印机", "sourceAnswer": "打印机", "analysis": "根据考纲书，输入设备的主要功能是接受用户输入的原始数据和程序，并将 其转换为计算机可以识别的二进制数据存入内存，例如键盘、鼠标、扫描仪 等。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q077-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-078", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "078", "type": "选择题", "stem": "关于显示器的说法，错误的是（ ）。", "options": {"A": "颜色位数越多越好", "B": "显示器越大越好", "C": "分辨率越高越好", "D": "刷新频率越高越好"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书， 显示器的性能通常由颜色位数、 分辨率和刷新频率等指标决定， 但显示器的尺寸并非越大越好，而是要根据使用需求、分辨率和观看距离来 选择合适的尺寸。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q078-1.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-20261014-215"}, {"id": "QFW-20260821-COMP-CH3-079", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "079", "type": "选择题", "stem": "液晶显示器（LCD）的分辨率指的是（ ）。", "options": {"A": "显示器的尺寸", "B": "显示器上像素的数量", "C": "显示器的亮度", "D": "显示器的对比度"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述， 在图像采样中，“采样的实质就是用多少个像素(Pixels) 点来描述这一幅图像， 称为图像的分辨率， 用‘列数×行数’表示， 分辨率越 高， 图像越清晰， 存储量也越大”。 液晶显示器的分辨率同样指的是屏幕上水 平和垂直方向上像素的总数。 因此，分辨率本质上表示的是像素数量，而非尺寸、亮度或对比度。 答案为：B", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q079-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-080", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "080", "type": "选择题", "stem": "计算机显示器采用（ ）模型显示颜色。", "options": {"A": "HSL", "B": "RGB", "C": "CMYK", "D": "LAB"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，计算机显示器采用 RGB（红、绿、蓝）颜色模型来显示颜色。 RGB 是一种加色模型， 通过不同亮度的红、绿、蓝三原色光的组合来呈现各 种颜色，广泛应用于显示设备，如计算机显示器、电视屏幕和手机屏幕。 值得注意的是，C 选项中的 CMYK（青、品红、黄、黑）是用于印刷的颜色 模型，而非计算机显示器使用的颜色模型。 HSL（色相、 饱和度、 亮度） 是一种颜色表示方法， 主要用于图像处理和设计 软件中， 不是计算机显示器的基础颜色模型。LAB 颜色模型是一种设备无关 的颜色表示方式，主要用于色彩校正和高精度色彩处理。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q080-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-081", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "081", "type": "多选题", "stem": "（多选）标准 VGA 显示器中使用的三基色是（ ）。", "options": {"A": "红色", "B": "紫色", "C": "绿色", "D": "蓝色"}, "verifiedAnswer": "ACD", "sourceAnswer": "ACD", "analysis": "根据考纲书，计算机显示器采用 RGB（红、绿、蓝）颜色模型来显示 颜色。RGB 是一种加色模型，通过不同亮度的红、绿、蓝三原色光的组合来 呈现各种颜色，广泛应用于显示设备，如计算机显示器、电视屏幕和手机屏 幕。 值得注意的是，C 选项中的 CMYK（青、品红、黄、黑）是用于印刷的颜色 模型，而非计算机显示器使用的颜色模型。 HSL（色相、 饱和度、 亮度） 是一种颜色表示方法， 主要用于图像处理和设计 软件中， 不是计算机显示器的基础颜色模型。LAB 颜色模型是一种设备无关 的颜色表示方式，主要用于色彩校正和高精度色彩处理。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q081-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-082", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "082", "type": "判断题", "stem": "要使用显示器 “真彩色” 的显示效果， 计算机显示适配器的颜色质量属性应该 至少设置为 24 位。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书， 真彩色通常指 24 位颜色深度， 即每个像素由 红、 绿、 蓝 （RGB） 三种颜色各 8 位 （共 24 位） 组成， 可以表示 16777216224 = （约 1677 万）种颜色。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q082-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-083", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "083", "type": "填空题", "stem": "打印机采用的颜色模式是 C（青） 、M（品红） 、Y（________）和 K（黑）。", "options": {}, "verifiedAnswer": "黄", "sourceAnswer": "黄", "analysis": "CMYK（青、品红、黄、黑）是用于印刷的颜色模型。其中 C 代表 Cyan，即 青色；M 代表 Magenta。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q083-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-084", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "084", "type": "判断题", "stem": "为了防止液晶显示器中的液态晶体挥发，其工作环境不宜太干燥，应保持足 够的湿度。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，液晶显示器中的液态晶体是密封在玻璃基板之间的， 具有较强的密封性， 不存在因空气干燥而挥发的问题。 同时， 液晶显示器更怕 潮湿， 高湿度环境反而可能导致电路受潮， 出现故障。 因此， 工作环境应保持 干燥通风，而不是“保持足够的湿度”。 因此，题干中的说法是错误的。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q084-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-085", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "085", "type": "选择题", "stem": "喷墨打印机的主要特点是（ ）。", "options": {"A": "噪声大", "B": "打印速度快", "C": "彩色印刷能力强", "D": "打印成本低"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书中的描述，喷墨打印机的主要优点是“色彩表现力强、可以打印 高质量的彩色图像”， 特别适用于图片、 照片和图形输出， 因而其“彩色印刷 能力强”是最突出的特点。 其他选项分析如下： A、喷墨打印机噪声相对较低； B、打印速度一般较慢，不如激光打印机； D、喷墨打印机的打印成本相对较高，墨盒更换频繁。 因此，答案为：C", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q085-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-086", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "086", "type": "填空题", "stem": "速度快、印字质量好、噪音低的打印机类型是________。", "options": {}, "verifiedAnswer": "激光打印机", "sourceAnswer": "激光打印机", "analysis": "根据考纲书， 激光打印机具有速度快、 印字质量好、 噪音低的特点。 它采用静 电成像技术和激光扫描技术，利用碳粉成像并通过高温定影，使打印效果清 晰细腻。同时，由于激光打印机没有撞击式打印头（针式打印机） ，其工作过 程噪音较低，因此广泛应用于办公环境。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q086-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-087", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "087", "type": "选择题", "stem": "（ ）以计算机模型文件为基础，运用粉末状塑料或金属等可黏合材料，通 过逐层打印的方式来构造物体的技术。", "options": {"A": "针式打印机", "B": "喷墨打印机", "C": "激光打印机", "D": "3D打印机"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，3D 打印机是一种以计算机模型文件为基础，使用粉末状塑料、 金属或其他可黏合材料，通过逐层打印的方式构造物体的技术。这种技术属 于增材制造，广泛应用于工业制造、医疗、建筑、艺术等领域。 A（针式打印机） 错误， 针式打印机采用撞击式打印技术，主要用于打印发票 等场景。 B（喷墨打印机）错误，喷墨打印机通过喷射墨滴来打印文本和图像，无法进 行三维成型。 C（激光打印机） 错误， 激光打印机利用静电成像原理进行高速高质量的二维 打印。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q087-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q087-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-088", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "088", "type": "选择题", "stem": "图像的打印精度单位是（ ）。", "options": {"A": "DPI", "B": "BPI", "C": "LPI", "D": "CPI"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，DPI（Dots Per Inch，每英寸点数）是衡量图像打印精度的单 位，表示打印设备每英寸可以打印的点数。 DPI 数值越高，打印精度越高， 图像越清晰。 A（DPI） 正确，DPI 是打印精度的标准单位， 常用于衡量打印机的分辨率， 如 300 DPI、600 DPI、1200 DPI 等。 B（BPI）错误，BPI（Bits Per Inch，每英寸位数）主要用于衡量磁盘存储 密度，而非打印精度。 C（LPI）错误，LPI（Lines Per Inch，每英寸线数） 用于衡量网点印刷的网 屏线数，适用于印刷行业，而非打印机精度。 D（CPI）错误，CPI（Characters Per Inch，每英寸字符数）通常用于衡量 打印机或打字机的字符间距，而非图像打印精度。 B、C、D 都是专升本考试中不太可能考到的术语，所以专注于 A（DPI）的 概念即可。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q088-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-089", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "25 主板", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "089", "type": "选择题", "stem": "在微型计算机中，主板有着重要的作用，它是其它部件和各种外部设备的 （ ）。", "options": {"A": "连接载体", "B": "通信主体", "C": "访问桥梁", "D": "控制中心"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，主板（Motherboard）是微型计算机的核心部件之一，它提供 了各个硬件部件（如 CPU、内存、硬盘、显卡等）以及外部设备（如鼠标、 键盘、打印机等）的连接载体。主板上集成了数据总线、芯片组、 接口等，确 保计算机各个组件之间的互连和数据传输。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q089-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-090", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "25 主板", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "090", "type": "选择题", "stem": "关于主板上的 PCH 芯片组，以下说法错误的是（ ）。", "options": {"A": "PCH芯片组主要负责USB接口、I/O接口、SATA接口等的控制", "B": "PCH芯片组位于主板上离CPU插槽较远的位置", "C": "PCH芯片组是主板上的一个非必要组件，可以被其他芯片替代", "D": "PCH芯片组负责高级能源管理"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，PCH（Platform Controller Hub，平台控制器集线器）是现 代主板上负责管理 I/O 接口、USB、SATA、PCIe、音频、网络等功能的重要 芯片组。PCH 取代了传统的北桥和南桥架构， 并与 CPU 协同工作， 因此是 主板上不可或缺的组件。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q090-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-091", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "25 主板", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "091", "type": "选择题", "stem": "固化在计算机主板上的基本输入/输出系统简写是（ ）。", "options": {"A": "HDMI", "B": "BIOS", "C": "SATA", "D": "QPI"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，BIOS（Basic Input/Output System，基本输入/输出系统）是 固化在计算机主板上的固件， 负责计算机的基本硬件初始化和引导操作系统。 BIOS 存储在主板上的 ROM（只读存储器）或 Flash 存储芯片中，是计算 机启动过程中最先运行的软件。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q091-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-092", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "25 主板", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "092", "type": "选择题", "stem": "计算机从启动到正常使用的过程中，不必经过的阶段是（ ）。", "options": {"A": "启动操作系统内核，装入加载程序", "B": "活动分区的引导扇区被装入内存", "C": "检查网络工作站是否连接到Internet", "D": "系统BIOS对硬件进行加电自检"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，微型计算机的启动过程通常包括以下步骤： ① 开机：计算机通电启动。 ② 自检（POST，自检程序） ：BIOS 进行基本硬件检测，确保各部件正常工 作。 ③ 执行 ROM 中的启动程序：BIOS 读取存储在 ROM（只读存储器） 中的 引导程序，并执行它。 ④ 加载操作系统： 引导程序从硬盘或其他存储设备中加载操作系统到内存中。 ⑤ 执行操作系统：操作系统完成初始化，用户可以使用计算机。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q092-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-093", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "25 主板", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "093", "type": "填空题", "stem": "微型计算机的启动过程如下图所示，其中空白处应该填写的是________。", "options": {}, "verifiedAnswer": "加载操作系统", "sourceAnswer": "加载操作系统", "analysis": "根据考纲书中的描述，微型计算机的启动过程包括以下几个步骤：先加电开 机，然后进行硬件自检，接着执行 ROM 中的启动程序，该启动程序会引导 加载操作系统， 最后进入操作系统环境。 因此， 图中空白处应填写“加载操作 系统”这一关键步骤。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q093-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q093-2.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q093-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-094", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "25 主板", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "094", "type": "选择题", "stem": "CMOS 芯片在主板上的作用是（ ）。", "options": {"A": "驱动和管理基本的输入/输出设备", "B": "存储系统配置参数和实时时钟", "C": "负责USB接口、I/O接口、SATA接口等的控制", "D": "处理CPU的运算任务"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，CMOS 芯片主要用于存储系统的配置信息和实时时钟 等数据。 这些信息包括硬盘参数、 启动顺序、 日期时间等， 它依赖主板上的电 池供电，以保证断电后信息不会丢失。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q094-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-095", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "095", "type": "选择题", "stem": "关于总线的概念，下列说法错误的是（ ）。", "options": {"A": "总线是计算机系统中各部件之间传输数据的公用通道", "B": "总线的带宽是共享的，连接的设备越多，每个设备的有效传输速率越低", "C": "总线可以采用点对点传输方式，每个设备独享带宽", "D": "总线仅用于CPU内部各部件之间的数据传输"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，总线是计算机系统中各部件之间传输数据的公用通道，用于连 接 CPU、内存、输入/输出设备等，实现数据、地址和控制信息的传输。 总线不仅用于 CPU 内部，还用于 CPU 与内存、存储设备、I/O 设备等之 间的数据通信，因此不局限于 CPU 内部。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q095-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-096", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "096", "type": "判断题", "stem": "在串行总线中，二进制数逐位通过一根数据线发送到目的部件，因此传输控 制比较简单，数据传输的频率较高。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书， 串行总线 （Serial Bus） 是一种数据传输方式， 它通过单条数据 线逐位传输二进制数据。由于串行传输的线路较少，减少了信号干扰和复杂 的同步控制，因此传输控制较简单。此外，现代串行总线（如 USB、PCIe、 SATA 等） 采用高速串行通信技术， 能够支持较高的数据传输频率， 甚至超过 传统的并行总线。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q096-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-097", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "097", "type": "选择题", "stem": "下列关于总线带宽的说法中，不正确的是（ ）。", "options": {"A": "工作频率越高，总线的物理长度越长", "B": "单位时间内传输次数越多带宽越高", "C": "总线工作频率越高带宽越高", "D": "总线位宽越多带宽越高"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，总线带宽指的是单位时间内总线所能传输的数据量，其计算公 式为： 总线带宽 = 单位时间内传输次数 × 数据传输率 × 位宽 影响总线带宽的主要因素包括： 单位时间内传输次数： 除了全双工 （即发送的同时可以接收） 的单位传输次数 为 2 之外，其它的传输方式，该值都固定为 1。 总线工作频率：频率越高，每秒传输的数据次数越多，带宽越高。 总线位宽：总线一次能传输的数据位数越多，带宽越高。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q097-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-098", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "098", "type": "判断题", "stem": "总线带宽是指总线能够同时传输的二进制位数。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "总线能够同时传输的二进制位数称为总线位宽， 而总线带宽 = 单位时间内传 输次数 × 数据传输率 × 位宽，因此题干的说法是错误的。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q098-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-099", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "099", "type": "填空题", "stem": "计算机总线的工作频率为 33MHz，总线的宽度为 64bit，则它的传输速率为 ________MB/s。", "options": {}, "verifiedAnswer": "264", "sourceAnswer": "264", "analysis": "总线带宽 = 单位时间内传输次数 × 数据传输率 × 位宽 因此，总线带宽 = 1×33MHz×64bit/8 = 264MB/s", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q099-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-100", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "100", "type": "选择题", "stem": "关于 I/O 接口的描述，下列（ ）是错误的。", "options": {"A": "I/O接口是连接外设和主机的桥梁，实现主机与外设之间的数据传输", "B": "程控式接口适用于连接速度较快的I/O设备，如硬盘驱动器", "C": "DMA式接口允许I/O设备和内存直接交换数据，不经过CPU", "D": "USB接口是一种广泛应用的串行总线接口，支持热插拔"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书（王移芝）中的描述，I/O 接口是“连接外部设备与主机的桥梁， 实现计算机与各种输入输出设备之间的数据传送”。不同的接口方式适用于 不同速度和复杂度的外设。 B 项描述是错误的： 程控式接口是指CPU 通过程序控制外设完成数据交换， 适用于速度较慢、 数据量小的设备， 如键盘、 鼠标等； 而速度较快、 数据量大 的设备 （如硬盘） 通常采用DMA（直接内存访问） 方式， 以减少CPU 负担。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q100-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-101", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "101", "type": "选择题", "stem": "在计算机系统中，DMA（Direct Memory Access ）的主要功能是（ ）。", "options": {"A": "提高CPU的处理速度", "B": "增加内存的存储容量", "C": "实现内存与外设之间的快速数据传送", "D": "连接不同类型的I/O设备"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书（王移芝）中的描述，DMA（直接内存访问）是一种重要的数据 传输方式， 它允许I/O 设备在不经过 CPU 参与的情况下， 直接与内存进行数 据交换， 显著提高了数据传输效率， 特别适用于磁盘、 显卡等高速设备与内存 之间的数据传送。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q101-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-102", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "102", "type": "填空题", "stem": "USB 接口是一种通用的________（串行/并行）总线接口，支持即插即用和 热插拔。", "options": {}, "verifiedAnswer": "串行", "sourceAnswer": "串行", "analysis": "根据考纲书，USB（Universal Serial Bus，通用串行总线）是一种串行总线 接口，用于连接计算机与外部设备。USB 采用串行数据传输方式，相较于传 统的并行接口（如并口打印机接口） ，它具有更高的传输效率，并支持即插即 用和热插拔功能，广泛用于键盘、鼠标、U 盘、移动硬盘等设备的连接。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q102-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-103", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "103", "type": "填空题", "stem": "如下图所示的连接符号是________接口。", "options": {}, "verifiedAnswer": "USB", "sourceAnswer": "USB", "analysis": "记住结论即可。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q103-1.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q103-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-104", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "104", "type": "选择题", "stem": "高清晰度的多媒体接口是（ ）。", "options": {"A": "USB", "B": "VGA", "C": "RJ-45", "D": "HDMI"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，HDMI（High-Definition Multimedia Interface，高清多媒 体接口） 是一种用于传输高清视频和音频的数字接口， 广泛应用于电视、 显示 器、投影仪和游戏机等设备。HDMI 具备高清晰度、无压缩、支持音视频同 步传输的特点，是当前主流的多媒体接口。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q104-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-105", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "105", "type": "选择题", "stem": "下列表示高清晰度多媒体接口的是（ ）。", "options": {"A": "原图选项 A", "B": "原图选项 B", "C": "原图选项 C", "D": "原图选项 D"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "A（HDMI） ，即标准的高清晰度多媒体接口，支持音视频同步传输。 B（Ethernet） ，即以太网的RJ-45 接口，用于网络通信。 C（SATA） ，即串行 ATA，是硬盘和主板之间的数据传输接口。 D（DVI） ，即数字视频接口，仅支持视频信号传输，不支持音频，因此不能 完全满足高清多媒体需求。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q105-1.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q105-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-106", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "106", "type": "选择题", "stem": "下列不属于微型计算机接口的是（ ）。", "options": {"A": "RJ-45", "B": "HDMI", "C": "ADSL", "D": "USB"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，微型计算机接口是用于连接计算机与其他设备的硬件接口，如 网络接口、显示接口、数据传输接口等。 A（RJ-45），RJ-45 是计算机网络接口，用于以太网连接（LAN）。 B（HDMI），HDMI 是高清多媒体接口，用于连接显示设备。 C（ADSL），ADSL（Asymmetric Digital Subscriber Line， 非对称数字用 户线路） 是一种宽带接入技术， 用于连接互联网， 而不是计算机的标准接口。 D（USB），USB（Universal Serial Bus） 是通用串行总线接口， 广泛用于数 据传输和外设连接。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q106-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-107", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "107", "type": "判断题", "stem": "SATA接口是一种高速的串行接口， 用于硬盘和内存之间的数据传输。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，SATA（Serial ATA， 串行高级技术附件） 是一种高速串行接口， 主要用于计算机主板与硬盘 （HDD、SSD） 、 光驱等存储设备之间的数据传输。 相比于早期的并行 ATA（PATA） 接口，SATA 具有传输速率更高、 数据线更 细、支持热插拔等优点。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q107-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-108", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "108", "type": "选择题", "stem": "关于 PCI 和 PCI-E 总线，下列描述正确的是（ ）。", "options": {"A": "PCI是一种串行总线，而PCI-E是并行总线", "B": "PCI-E的数据传输速率低于PCI", "C": "PCI-E是PCI的扩展标准，采用多通道的串行总线", "D": "PCI总线的带宽是独享的，而PCI-E总线的带宽是共享的"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书中的描述， PCI-E （全称为 Peripheral Component Interconnect Express） 是对传统PCI 总线的改进与替代， 是一种高速的串 行通信总线，支持点对点连接，每个设备拥有独立的通信通道，不再共享带 宽。PCI-E 采用“多通道串行结构”，通道数可扩展，如 x1、x4、x8、x16 等，实现更高的数据传输速率。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q108-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-109", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "109", "type": "选择题", "stem": "PCI 是一种 32 位的并行总线，总线频率为 33MHz，可扩展为 64 位并提高 到 66MHz 。由此可知，PCI 总线的最大带宽是（ ）。", "options": {"A": "132 MBps", "B": "250 MBps", "C": "500 MBps", "D": "528 MBps"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书中的描述与计算公式，计算 PCI 总线带宽的基本公式如下： 带宽 = 单位时间内传输次数 × 数据位数 × 总线频率 ÷ 8（换算为字节） 对于题中给出的 64 位 × 66MHz 的扩展 PCI 总线： 带宽 = 1 × 64 位 × 66 MHz ÷ 8 = 528 MBps 因此，答案为：D", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q109-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-110", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "110", "type": "选择题", "stem": "单通道的 PCI-E 3.0 的带宽是 8Gbps，则 16 通道（x16）的 PCI-E 3.0 的带 宽是（ ）。", "options": {"A": "1GBps", "B": "16GBps", "C": "128GBps", "D": "256GBps"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，PCI-E 总线采用多通道串行通信结构，其带宽是按通 道线性叠加的。PCI-E 3.0 单通道带宽为 8Gbps，而 1 字节 = 8 位，因此 换算为字节为： 单通道带宽 = 8 Gbps ÷ 8 = 1 GBps 那么 16 通道（x16）下的总带宽为： 1 GBps × 16 = 16 GBps 因此，答案为：B", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q110-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-111", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "111", "type": "填空题", "stem": "根据总线上传输信号的不同， 可将总线分为地址总线、 数据总线和________。", "options": {}, "verifiedAnswer": "控制总线", "sourceAnswer": "控制总线", "analysis": "根据考纲书，计算机的总线按传输的信号类型可以分为三类： ① 地址总线（Address Bus） ：用于传输内存地址或 I/O 设备地址。地址总 线的位宽决定了 CPU 的最大寻址空间。例如，32 位的地址线，最大寻址空 间为：232B = 4GB ② 数据总线（Data Bus） ：用于传输计算机内部的实际数据。数据总线的位 宽一般等于 CPU 的字长，即 CPU 一次能处理的二进制数的最大位数。 ③ 控制总线 （Control Bus） ： 用于传输控制信号， 以协调 CPU、 内存和 I/O 设备的工作。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q111-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-112", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "112", "type": "选择题", "stem": "地址总线的位宽是 32b，则其最大寻址能力是（ ）。", "options": {"A": "1GB", "B": "2GB", "C": "4GB", "D": "8GB"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书， 地址总线用于传输内存地址或 I/O 设备地址。 地址总线的位宽 决定了 CPU的最大寻址空间。32 位的地址线， 最大寻址空间为：232B = 4GB。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q112-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-113", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "113", "type": "选择题", "stem": "数据总线的位宽决定了（ ）。", "options": {"A": "CPU的字长", "B": "计算机的寻址空间", "C": "CPU的工作频率", "D": "总线的带宽"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书中的描述，“数据总线是用来传送数据的通道，其位宽表示一次 可以并行传送的二进制位数”，这直接关系到 CPU 一次能处理多少位数据， 也就是 CPU 的字长。 因此， 数据总线的位宽决定了CPU 的字长， 是CPU 性 能的重要指标之一。 其他选项分析： B、寻址空间是由地址总线的位数决定的； C、CPU 的工作频率由内部时钟决定； D、 总线的带宽与数据总线的位宽和总线频率共同决定， 不能单独由数据总线 位宽决定。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q113-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-114", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "27 软件基础", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "114", "type": "填空题", "stem": "软件 = ________ + ________ + ________。", "options": {}, "verifiedAnswer": "程序，数据，文档", "sourceAnswer": "程序，数据，文档", "analysis": "根据考纲书中的描述，计算机软件是“在计算机硬件设备上运行的各种程序 及其相关文档和数据的总称”。 也就是说， 软件不仅包括执行指令的程序， 还 包括用于支持程序运行的数据和相关的说明、帮助、配置等文档。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q114-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-115", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "27 软件基础", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "115", "type": "填空题", "stem": "软件系统分为________软件和________软件。", "options": {}, "verifiedAnswer": "系统，应用", "sourceAnswer": "系统，应用", "analysis": "根据考纲书，软件系统通常分为两大类： 系统软件：用于管理计算机硬件资源并为应用软件提供运行环境，例如操作 系统（Windows、Linux） 、驱动程序、编译器等。 应用软件：用于满足用户特定需求的程序，例如办公软件（Word、Excel）、 浏览器、游戏、图像处理软件等。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q115-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-116", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "27 软件基础", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "116", "type": "选择题", "stem": "以下（ ）是系统软件。", "options": {"A": "Photoshop", "B": "UNIX", "C": "Chrome", "D": "3Ds MAX"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，系统软件包括“操作系统（如 Windows、Mac OS、 UNIX、Linux 等） 、语言处理程序和实用程序”，是用于“管理计算机硬件 和软件资源， 并为应用程序提供支持的软件”。 其中，UNIX 是一种多用户、 多任务的操作系统，属于典型的系统软件。 其他选项： A、Photoshop 是图像处理类的应用软件； C、Chrome 是网页浏览器，也属于应用软件； D、3Ds MAX 是三维建模和渲染软件，同样是应用软件。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q116-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-117", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "27 软件基础", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "117", "type": "填空题", "stem": "数据处理软件有两类，通用应用软件和________。其中，学生选课系统属于 ________。", "options": {}, "verifiedAnswer": "专用应用软件，专用应用软件", "sourceAnswer": "专用应用软件，专用应用软件", "analysis": "根据考纲书中的描述，应用软件分为两类：“通用应用软件”和“专用应用 软件”。其中，“专用应用软件”是指为完成某一类或某一单位特定任务而 开发的软件，如各单位的管理信息系统等”。学生选课系统正是服务于学校 教务管理的特定功能，因此属于专用应用软件。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q117-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q117-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-118", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "27 软件基础", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "118", "type": "选择题", "stem": "实用程序完成一些与管理计算机系统资源及文件有关的任务， （ ）不属于 实用程序。", "options": {"A": "Windows", "B": "Windows优化大师", "C": "备份程序", "D": "WinRAR压缩软件"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书， 实用程序 （Utility Programs） 是系统软件的一种， 主要用于管 理计算机资源、优化系统性能、文件管理和数据备份等。例如：磁盘清理工 具、压缩软件、杀毒软件、备份工具等。 A（Windows）是操作系统，属于系统软件，而不是专门的实用程序。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q118-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-119", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "27 软件基础", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "119", "type": "选择题", "stem": "下列各组软件中，全部属于应用软件的是（ ）。", "options": {"A": "程序语言处理程序、操作系统、数据库管理系统", "B": "文字处理程序、编辑程序、UNIX", "C": "视频播放软件、图像处理软件、Windows 10", "D": "财务处理软件、金融软件、办公自动化软件"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书， 应用软件是用于满足用户特定需求的软件， 例如办公软件、 财务 软件、多媒体软件等，而系统软件则用于管理计算机资源并提供基本运行环 境。 A 选项中的操作系统,B 选项中的 UNIX 和 C 选项中 Windows 10 都是系统 软件，不属于应用软件的范畴。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q119-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-120", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "120", "type": "选择题", "stem": "计算机能直接执行的程序是（ ）。", "options": {"A": "源程序", "B": "机器语言程序", "C": "高级语言程序", "D": "汇编语言程序"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，计算机只能直接识别和执行机器语言编写的程序。机器语言由 二进制代码 （0 和 1） 组成， 每条指令对应计算机硬件可以直接执行的操作。 相比于高级语言（如 C、Java）和汇编语言，机器语言不需要翻译，可以被 计算机的 CPU 直接识别并执行。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q120-1.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-20261014-199"}, {"id": "QFW-20260821-COMP-CH3-121", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "121", "type": "判断题", "stem": "机器语言和汇编语言编写的程序的运行效率低于高级语言，所以机器语言和 汇编语言称为低级语言。 （ ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，机器语言和汇编语言属于低级语言，但它们的运行效率并不低 于高级语言，反而通常比高级语言更高效。机器语言和汇编语言之所以称为 低级语言，是因为它们是面向机器的，距离人类的自然语言更远。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q121-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-122", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "122", "type": "选择题", "stem": "对于汇编语言的评述中， （ ）是不正确的。", "options": {"A": "汇编语言采用助记符来代替机器语言中的指令和数据，又称为符号语言", "B": "汇编语言运行速度快，适于编制实时控制应用程序", "C": "汇编语言有编译型和解释型", "D": "机器语言、汇编语言和高级语言是计算机语言发展的3个阶段"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书中的描述， 汇编语言是介于机器语言与高级语言之间的低级语言， 它“采用助记符代替机器语言中的操作码和地址码，也称为符号语言”，并 且“运行速度快，适合用于实时控制等对性能要求较高的场合”。但汇编语 言并不具备编译型或解释型的分类，这种分类方式是针对高级语言的。汇编 语言必须通过汇编程序翻译成机器语言才能执行，不属于编译型或解释型语 言。 因此，C 项说法是错误的。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q122-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-123", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "123", "type": "选择题", "stem": "高级程序设计语言的主要优点是（ ）。", "options": {"A": "不需要翻译就能被计算机执行", "B": "执行效率与机器语言相当", "C": "易于学习、使用和维护", "D": "占用的存储空间更少"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书中的描述，高级语言的主要特点是“接近自然语言，易于理解和 掌握， 具有较强的可读性， 便于程序的书写、 调试和维护”， 这使得它广泛应 用于各种软件开发任务中。 选项分析： A、 错误， 高级语言不能被计算机直接执行， 必须通过编译或解释程序转换为 机器语言； B、 错误， 虽然现代编译器优化能力较强， 但高级语言执行效率通常仍低于机 器语言； D、错误，高级语言的程序通常比机器语言占用更多的存储空间。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q123-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-124", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "124", "type": "选择题", "stem": "用高级语言编写的程序称为（ ）。", "options": {"A": "源程序", "B": "编译程序", "C": "可执行程序", "D": "编辑程序"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书中的描述，用高级语言编写的程序称为源程序，它不能直接被计 算机执行，必须通过编译程序或解释程序将其转换成机器语言程序（即目标 程序或可执行程序）后，计算机才能执行。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q124-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q124-2.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-20261014-196"}, {"id": "QFW-20260821-COMP-CH3-125", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "125", "type": "填空题", "stem": "计算机高级程序设计语言翻译为机器语言的方式有编译方式和 ________方 式", "options": {}, "verifiedAnswer": "解释", "sourceAnswer": "解释", "analysis": "根据考纲书中的描述，高级语言不能被计算机直接识别执行，必须通过“编 译方式或解释方式”翻译为机器语言程序。编译方式是将整个源程序一次性 翻译成可执行的目标代码，而解释方式则是边翻译边执行，每次执行时都需 要解释器对源代码逐行翻译。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q125-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-126", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "126", "type": "选择题", "stem": "关于语言处理程序的描述，下列（ ）是错误的。", "options": {"A": "汇编程序将汇编语言编写的源程序翻译成机器语言程序", "B": "解释程序在执行源程序时，每次运行都需要重新解释", "C": "编译程序在编译过程中发现语法错误时，会生成目标文件", "D": "Java和Python是典型的解释型语言"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书中的描述， 语言处理程序包括汇编程序、 编译程序和解释程序。 具 体来说： A、正确，汇编程序将汇编语言翻译成机器语言； B、正确，解释程序的特点是“每次执行时都需要重新解释”； C、错误，编译程序在发现语法错误时， 会中止编译并报告错误，不会生成目 标文件； D、正确，Java 和 Python 都是解释型语言的代表，Java 使用虚拟机解释执 行，Python 直接由解释器执行源程序。 因此，答案为：C", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q126-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-127", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "127", "type": "选择题", "stem": "解释程序的执行速度相对较慢的原因是（ ）。", "options": {"A": "每次运行都需要重新解释", "B": "无法对整个程序进行优化", "C": "程序较大时，前面的运行是无效的", "D": "以上全部"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书中的描述，解释程序是一种边翻译边执行的程序语言处理方式， 它的执行速度慢，原因主要包括： A、 每次运行都需要重新解释， 不能像编译程序那样一次性生成目标文件后直 接运行； B、解释程序无法对整个程序进行全局优化，因为它不事先分析整体结构； C、程序较大时，如果出错或中断，前面的解释执行结果不会保存， 需重新从 头开始。 以上所有因素都导致了解释程序相较于编译程序而言，执行速度较慢。 因此，答案为：D", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q127-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-128", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "128", "type": "选择题", "stem": "Basic、Java、JavaScript和 Python 属于（ ）的语言。", "options": {"A": "汇编型", "B": "解释型", "C": "编译型", "D": "连接型"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，Basic、Java、JavaScript 和 Python 都属于解释型 语言的典型代表。解释型语言的程序在运行时需要借助解释器逐行翻译并执 行，这使得它们开发灵活、调试方便，但运行效率相对较低。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q128-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-129", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "129", "type": "选择题", "stem": "在编译方式的语言处理程序中，编译后的目标程序（ ）。", "options": {"A": "可以直接执行", "B": "需要与其他程序或库函数连接后才能执行", "C": "每次修改源程序后不需要重新编译", "D": "执行速度比解释方式慢"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，编译方式是将整个源程序一次性翻译成机器语言目标 程序，但该目标程序通常还需要与系统提供的标准库函数或其他模块进行连 接， 生成最终可执行文件， 这一步称为“链接”。 只有链接完成后， 程序才能 真正被执行。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q129-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-130", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "130", "type": "选择题", "stem": "解释程序和编译程序在处理源程序时的主要区别是（ ）。", "options": {"A": "解释程序逐句执行源程序，编译程序整体编译源程序", "B": "解释程序适用于高级语言，编译程序适用于汇编语言", "C": "解释程序生成目标程序，编译程序不生成目标程序", "D": "解释程序执行速度通常比编译程序快"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书中的描述，解释程序和编译程序的最大区别在于处理方式不同： 解释程序是边翻译边执行，逐句解释源程序；而编译程序是一次性将整个源 程序翻译成目标程序，之后再运行目标程序。这是两者在语言处理机制上的 本质区别。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q130-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-131", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "131", "type": "填空题", "stem": "下图中①处应填写________。", "options": {}, "verifiedAnswer": "汇编程序", "sourceAnswer": "汇编程序", "analysis": "根据考纲书，汇编语言源程序需要经过汇编程序的翻译，才能转换为机器语 言程序，供计算机直接执行。 图中①的作用是将汇编语言转换为机器语言，这一过程由汇编程序完成。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q131-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q131-2.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q131-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-132", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "132", "type": "填空题", "stem": "下图中①处应填写________。", "options": {}, "verifiedAnswer": "解释程序", "sourceAnswer": "解释程序", "analysis": "根据考纲书， 图示流程表示高级语言源程序直接执行， 并产生计算结果， 这符 合解释程序（Interpreter）的工作方式。 解释程序的特点： ① 逐行翻译并立即执行，不会生成目标程序和可执行文件。 ② 适用于 Python、JavaScript、BASIC 等语言。 ③ 每次运行时都需要解释器，因此执行速度通常比编译程序慢。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q132-1.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q132-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-133", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "133", "type": "选择题", "stem": "下图中①和②处应填写（ ）。", "options": {"A": "解释程序，编译程序", "B": "编译程序、解释程序", "C": "编译程序，连接程序", "D": "连接程序、编译程序"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书， 该图示表示 C 语言程序的编译和执行过程， 涉及两个关键步骤： 源程序（.c）→ 目标程序（.obj） ① 由编译程序完成，将高级语言转换为机器语言的目标文件（.obj）； ② 目标程序（.obj）→ 可执行程序（.exe） 由连接程序完成， 它负责将多个目标文件 （如 .obj 文件） 与库文件链接生成 最终的可执行程序（.exe）。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q133-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q133-2.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q133-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-134", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "134", "type": "选择题", "stem": "1954 年，世界上首次出现的高级语言是（ ）语言。", "options": {"A": "C", "B": "Fortran", "C": "Python", "D": "Java"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，1954 年 IBM 公司研制出了世界上第一种高级程序设 计语言——Fortran（Formula Translation），主要用于科学计算。 这标志着 计算机语言由机器语言和汇编语言向更高级抽象层次发展的重要一步。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q134-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-135", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "135", "type": "选择题", "stem": "以下程序设计语言中， 采用虚拟机技术， 因而具有良好跨平台特性的是 （ ）。", "options": {"A": "Java", "B": "C++", "C": "C#", "D": "VB"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，Java 语言采用 Java 虚拟机（JVM，Java Virtual Machine） 技术，使其具备良好的跨平台特性。Java 源代码首先被编译为字节码，然后 由 JVM 在不同操作系统上解释执行，做到“一次编写，到处运行”。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q135-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-136", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "136", "type": "选择题", "stem": "（ ）被称为“胶水语言”，常用于将不同模块联结在一起。", "options": {"A": "Java语言", "B": "Python语言", "C": "C#语言", "D": "Basic语言"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书中的描述，Python 语言由于其语法简洁、 扩展性强和对多种库的 良好支持， 被广泛用于集成不同的系统模块和调用其他语言编写的程序模块， 因此被誉为“胶水语言”。这使得它在人工智能、数据分析、Web开发等领 域都有广泛应用。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q136-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-137", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "137", "type": "选择题", "stem": "Python 是一种面向对象的（ ）。", "options": {"A": "编译型语言", "B": "解释型语言", "C": "汇编型语言", "D": "非结构化语言"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，Python 是一种面向对象的解释型语言， 其代码逐行解释执行， 不需要编译成二进制机器码。Python 代码由 Python 解释器直接运行，适 用于快速开发、数据分析、人工智能等领域。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q137-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-138", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "第三章 综合应用题", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "138", "type": "综合题", "stem": "计算机的工作过程就是执行 ① 的过程。\n第一台计算机 ② 的诞生仅仅表明人类发明了计算机， 从而进入了 “计算” 时\n代。对后来的计算机在体系结构和工作原理上具有重大影响的是在同一时期\n由美籍匈牙利数学家 ③ 和他的同事们研制的 ④ 计算机，采用了“ ⑤ ”\n的思想。\n①_________\n②_________\n③_________\n④_________\n⑤ ________", "options": {}, "verifiedAnswer": "① 程序 ② ENIAC ③ 冯·诺依曼 ④ EDV AC ⑤ 存储程序或存储程序控制", "sourceAnswer": "① 程序 ② ENIAC ③ 冯·诺依曼 ④ EDV AC ⑤ 存储程序或存储程序控制", "analysis": "根据考纲书中的描述： ① “计算机的工作过程就是执行程序的过程”； ② “ 第一台计算机 ENIAC 的诞生表明人类发明了计算机，从而进入了‘计 算’时代”； ③ “对后来计算机在体系结构和工作原理上具有重大影响的是在同一时期由 美籍匈牙利数学家冯·诺依曼和他的同事们”； ④ “研制的 EDV AC计算机”； ⑤ “在 EDV AC中采用了‘存储程序’的思想”。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q138-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q138-2.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-139", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "第三章 综合应用题", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "139", "type": "综合题", "stem": "冯·诺依曼机的结构如下图所示：\n程序和数据通过输入设备，以同等地位存放在 ① 中，并按 ④ 寻访。程序\n和数据以二进制表示， 因此数据存储的最小单位为一个二进制位 （比特，bit），\n基本单位为 ⑤ 。\n② 是计算机中进行数据加工的部件，主要由算术逻辑单元（ Arithmetic\nand Logic Unit，ALU） 、浮点运算部件（Floating Point Unit，FPU，用来\n提高浮点运算速度）和各种寄存器组成。 “②”的主要功能是执行数值数据的\n算术加、减、乘、除等运算，执行逻辑数据的与、或、 非等逻辑运算，以及移\n位（左移、右移）运算。\n③ 是计算机的指挥中枢，用于控制计算机各个部件按照指令的功能要求协\n同工作。 其基本功能是从 “①” 处取指令、 分析指令和向其它部件发出控制信\n号。 “③”的主要部件由程序计数器（PC） 、指令寄存器（IR） 、指令译码器\n（ID） 、时序控制电路以及微操作控制电路等组成。\n70多年来，虽然计算机系统从性能指标、运算速度、工作方式、应用领域和\n价格等方面与早期计算机存在很大差别，但基本结构没有变，仍然属于冯·诺\n依曼计算机。\n①_________\n②_________\n③_________\n④_________\n⑤ ________", "options": {}, "verifiedAnswer": "① 内存 ② 运算器 ③ 控制器 ④ 地址 ⑤ 字节", "sourceAnswer": "① 内存 ② 运算器 ③ 控制器 ④ 地址 ⑤ 字节", "analysis": "根据考纲书中的描述，冯·诺依曼机的基本结构包括五大部分：存储器、输入 设备、 输出设备、 运算器和控制器。 图中的①②③分别对应这五大部件中的关 键组成部分： ① 是内存储器的一部分， 程序和数据通过输入设备送入并“以同等地位存放 在存储器中”，因此①应为 内存储器； ② 是负责数据加工的部件，为运算器； ③ 是指挥中枢，用于控制各部件协同工作的，为控制器； ④ 描述的是“按地址寻访”程序和数据； ⑤ 数据存储的基本单位是字节（Byte）。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q139-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q139-2.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q139-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-140", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "第三章 综合应用题", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "140", "type": "综合题", "stem": "小伟同学即将毕业，应聘到一家创意设计公司做视频处理工作。为了在家里\n就能工作， 需配置一台高性能电脑， 教计算机课程的张老师给出了如下建议：\n所购电脑的内核最好是 ① 的，内存为 ② ，操作系统和应用程序最好安装\n在 ③ 里，视频处理软件建议采用 ④ ， 为了连接高清显示设备最好配置 ⑤\n接口。\n① A、单核 B、双核 C、四核 D、八核\n② A、8GB B、16GB C、8GHz D、16GHz\n③ A、HD B、CD C、DVD D、SSD\n④ A、Goldwave B、Photoshop C、Premiere D、Authorware\n⑤ A、VGA B、DVI C、HDMI D、FW1394", "options": {}, "verifiedAnswer": "① D，② B，③ D，④ C，⑤ C", "sourceAnswer": "① D，② B，③ D，④ C，⑤ C", "analysis": "结合考纲书中的多媒体技术和硬件系统相关内容： ① 内核选项：在进行视频处理这类对并发处理能力要求较高的任务时， 多核 CPU 可以显著提高处理效率。八核（D）更具性能优势，适合高负载任务。 ② 内存选项：内存越大，能够同时运行更多程序并处理更大规模的数据。 16GB 是当前中高端多媒体处理的合理选择。 ③ 操作系统安装位置：SSD（固态硬盘）是外存中读写速度最快的，是当前 主流操作系统与大型应用程序的首选安装介质。 ④ 视频处理软件：Premiere 是 Adobe 公司专为视频剪辑与处理设计的专 业软件，常用于影视后期，是公认的专业视频编辑工具。 ⑤ 显示输出接口：HDMI（高清晰度多媒体接口） 是目前主流的高清视频和 音频传输接口， 广泛用于连接高清显示设备， 优于 VGA、DVI 等传统接口。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q140-1.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q140-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-141", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "第三章 综合应用题", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "141", "type": "综合题", "stem": "疫情期间，小小唐打算 DIY 一台计算机，以满足学习的需要。她通过京东，\n在线购买了 CPU、内存条、SATA接口的固态硬盘、PCI-E x16 接口的显卡\n和一块主板。装机时，她需要将这些硬件设备安装在主板上，如下图所示：\nⅠ 编号处的接口与小小唐购买的硬件之间的对应关系：\n①_________\n②_________\n③_________\n④_________\nⅡ 编号为⑤的位置，散热风扇下的芯片是________。", "options": {}, "verifiedAnswer": "① CPU ② 内存条 ③ 显卡 ④ 固态硬盘 ⑤ PCH 芯片", "sourceAnswer": "① CPU ② 内存条 ③ 显卡 ④ 固态硬盘 ⑤ PCH 芯片", "analysis": "根据考纲书中对主板结构的介绍和常识性硬件知识： ① 为主板中央的 CPU 插槽，形状和位置正是安装处理器的位置； ② 为 内存插槽 （DIMM） ， 用于插入内存条， 通常为长条形， 多个并排排列； ③ 为 PCI-E x16 插槽， 是专门为 显卡设计的高速插槽， 一般位于主板中部 偏左； ④ 为 SATA 接口区域，SATA 固态硬盘连接到这里； ⑤ 位于主板南桥区域，有主动散热设计，该芯片为 PCH（Platform Controller Hub） 芯片， 主要负责 I/O 接口、 存储控制等， 是现代主板的核 心控制组件之一。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q141-1.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q141-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-142", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "第三章 综合应用题", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "142", "type": "综合题", "stem": "小李自己采购主板、CPU、内存条、硬盘、机箱和电源组装了一台计算机，\n要使该计算机能办公、上网，简述接下来还应该完成的工作。", "options": {}, "verifiedAnswer": "① 如果 CPU 不带核显，那么还需要采购并安装独立显卡； ② 磁盘分区并格式化，安装操作系统； ③ 安装办公软件，例如微软的 Office 或金山的 WPS。 一切正常的话到此可以办公。 ① 按需额外采购网卡和路由器等网络硬件，并向 ISP 申请上网账号； ② 安装并配置 TCP/IP 协议，包括 IP 地址、子网掩码、网关地址和 DNS 服 务器； ③ 使用 ISP 提供的账号密码，连接并登录 Internet。 一切正常的话到此即可上网。", "sourceAnswer": "① 如果 CPU 不带核显，那么还需要采购并安装独立显卡； ② 磁盘分区并格式化，安装操作系统； ③ 安装办公软件，例如微软的 Office 或金山的 WPS。 一切正常的话到此可以办公。 ① 按需额外采购网卡和路由器等网络硬件，并向 ISP 申请上网账号； ② 安装并配置 TCP/IP 协议，包括 IP 地址、子网掩码、网关地址和 DNS 服 务器； ③ 使用 ISP 提供的账号密码，连接并登录 Internet。 一切正常的话到此即可上网。", "analysis": "根据考纲书中的描述，一台计算机在组装完硬件后，要实现完整功能（如办 公、上网） ，还需完成以下软件和网络配置步骤： 第一阶段：使计算机能办公 “计算机硬件是物质基础，而计算机软件则是在硬件上运行的各种程序及其 相关文档和数据，用于指挥计算机工作”，必须安装操作系统和应用软件才 能投入使用。 此外，若 CPU 不带核显，“则需额外安装显卡”以实现基本图形显示功能。 第二阶段：实现上网功能 要上网还需具备网络设备和协议支持，包括： “安装网卡”、“配置 TCP/IP 协议（如 IP 地址、子网掩码、网关、DNS 等）”，以及“使用 ISP 提供的账号进行拨号上网”。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q142-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-143", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "第三章 综合应用题", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "143", "type": "综合题", "stem": "某公司购买了一批电脑，配置是4 核 CPU、2GB 内存、1TB 的机械硬盘。 为\n优化系统：\n① 计算机系统由哪两部分组成？并描述两者之间的关系。\n② 不更换硬件的情况下，为提高计算机性能，请增加两个硬件。\n③ 请列举一款国产办公软件。", "options": {}, "verifiedAnswer": "① 完整的计算机系统由硬件系统和软件系统组成， 硬件是基础， 软件是灵魂； ② 增加内存，增加固态硬盘； ③ WPS 或永中 Office。", "sourceAnswer": "① 完整的计算机系统由硬件系统和软件系统组成， 硬件是基础， 软件是灵魂； ② 增加内存，增加固态硬盘； ③ WPS 或永中 Office。", "analysis": "① 计算机系统由哪两部分组成？ 根据考纲书中的描述： “一个完整的计算机系统由硬件系统和软件系统组 成”， 其中“硬件是软件建立和依托的基础， 软件是计算机系统的灵魂”。两 者相辅相成，硬件没有软件无法工作，软件没有硬件无法运行。 ② 不更换原有硬件的前提下，增加两个能提升性能的硬件 虽然题目限制“不更换”，但允许“增加”硬件。在现有基础上，增加： 内存条：2GB 内存不足，扩展内存可提升多任务处理能力（以 PC 机来说， 目前主流是 8GB~32GB）； 固态硬盘（SSD） ：作为系统盘使用，可显著加快操作系统和软件启动速度。 这两项升级均能在不替换主机核心硬件的情况下，显著优化整体性能。 ③ 国产办公软件 考纲书中提及：“常见国产办公软件包括金山 WPS Office、 永中Office 等”。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q143-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-144", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "第三章 综合应用题", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "144", "type": "综合题", "stem": "简述机器语言、汇编语言、高级语言的特点。", "options": {}, "verifiedAnswer": "机器语言：计算机唯一能识别和直接执行的语言；低级语言，面向机器。 汇编语言： 机器语言的助记符， 需要经过 “汇编” 过程翻译成机器语言代码； 低级语言，面向机器。 高级语言：接近人类自然语言，大多具有平台无关性。 低级语言的可读性差、 开发效率低、 可移植性差， 但执行效率高； 高级语言的 可读性高、开发效率高、可移植性好，但执行效率低。", "sourceAnswer": "机器语言：计算机唯一能识别和直接执行的语言；低级语言，面向机器。 汇编语言： 机器语言的助记符， 需要经过 “汇编” 过程翻译成机器语言代码； 低级语言，面向机器。 高级语言：接近人类自然语言，大多具有平台无关性。 低级语言的可读性差、 开发效率低、 可移植性差， 但执行效率高； 高级语言的 可读性高、开发效率高、可移植性好，但执行效率低。", "analysis": "根据考纲书中的描述： 机器语言 是“计算机唯一能直接识别和执行的语言 ”，“由二进制代码组 成”，操作效率高，但“难以理解和编写”，属于低级语言，面向机器。 汇编语言 是“使用助记符代替机器指令”的语言，也属于低级语言。“汇编 语言需要通过汇编程序翻译成机器语言后才能执行”，仍然面向底层硬件， 但可读性略高于机器语言。 高级语言 是“接近自然语言， 具有良好的可读性和易用性”，如 C、Python、 Java 等，面向人类用户，具有平台无关性，需要通过编译或解释才能运行。 总结比较： 低级语言 （机器语言和汇编语言） 执行效率高但开发效率低、 可读 性差；高级语言可移植性好、开发效率高，但执行效率低。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q144-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-145", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "第三章 综合应用题", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "145", "type": "综合题", "stem": "高级语言的翻译程序有两种工作方式，如下图所示，回答问题。\n① 图（上）描述的过程是________；图（下）描述的过程是________；\n② 图中标识为“Ⅰ、Ⅱ、Ⅲ”处对应的是：\nⅠ ________，Ⅱ ________，Ⅲ ________。", "options": {}, "verifiedAnswer": "① 解释、编译，② 解释程序、编译程序、连接程序", "sourceAnswer": "① 解释、编译，② 解释程序、编译程序、连接程序", "analysis": "根据考纲书中的描述，高级语言的翻译程序有两种工作方式：解释方式和编 译方式。 ① 图（上）中，程序边解释边执行，不生成中间目标文件，这是典型的解释 过程； 图（下）中，源程序 .c 被先编译成目标程序 .obj，再通过连接程序生成可 执行文件 .exe，这是典型的编译过程。 ② 对应图中的模块： Ⅰ 是负责直接读取源程序并边翻译边执行的，称为 解释程序； Ⅱ 是将源程序一次性翻译为目标代码的，是 编译程序； Ⅲ 是将目标代码和库函数链接生成最终可执行程序的，是 连接程序。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q145-1.jpg", "images/qb201/question-images/qfw-20260821-ch3/q145-2.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw-20260821-ch3/q145-1.jpg"}, {"id": "QFW-20260821-COMP-CH3-146", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "第三章 综合应用题", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "146", "type": "综合题", "stem": "简述解释和编译两种模式的区别。", "options": {}, "verifiedAnswer": "---（必答）--- 解释方式由解释程序完成， 逐条翻译， 不生成目标代码文件； 每次执行都需要 再次解释。 Ⅰ Ⅱ Ⅲ 编译方式由编译程序完成， 整体翻译， 会生成目标代码文件和可执行文件； 编 译一次后可以多次运行。 ---（可选）--- 解释方式效率低，安全性低； 编译方式效率高，安全性也更高，是大多数高级语言采用的转换方式。", "sourceAnswer": "---（必答）--- 解释方式由解释程序完成， 逐条翻译， 不生成目标代码文件； 每次执行都需要 再次解释。 Ⅰ Ⅱ Ⅲ 编译方式由编译程序完成， 整体翻译， 会生成目标代码文件和可执行文件； 编 译一次后可以多次运行。 ---（可选）--- 解释方式效率低，安全性低； 编译方式效率高，安全性也更高，是大多数高级语言采用的转换方式。", "analysis": "根据考纲书中的描述， 高级语言的翻译方式分为两种： 解释方式和编译方式， 两者区别如下： 解释方式： 由解释程序完成，“逐句地将源程序翻译成机器语言并立即执行”， 不生成目标代码文件， 且“每次运行都需要重新解释”， 因此效率较低， 适合 调试和教学使用。 编译方式： 由编译程序完成，“将整个源程序一次性翻译为目标程序”， 并通 过连接程序生成可执行文件， 之后可重复运行而无需再次翻译， 执行效率高、 保密性也较强，是工业界主流采用的方式。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q146-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-20260821-COMP-CH3-147", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "第三章 综合应用题", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 全方位课后练习", "batch": "全方位课后练习", "sourceNo": "147", "type": "综合题", "stem": "指令和程序有什么区别？试述计算机执行指令的过程？", "options": {}, "verifiedAnswer": "指令是能够被计算机识别并执行的二进制编码，又称为机器指令。程序是指 令的有序集合，用于完成一个特定的功能。 指令的执行过程分为 3 个步骤：取指令、分析指令和执行指令，一条指令执 行完成，程序计数器加 1 或将转移地址码送入程序计数器，继续重复执行下 一条指令。如下图所示：", "sourceAnswer": "指令是能够被计算机识别并执行的二进制编码，又称为机器指令。程序是指 令的有序集合，用于完成一个特定的功能。 指令的执行过程分为 3 个步骤：取指令、分析指令和执行指令，一条指令执 行完成，程序计数器加 1 或将转移地址码送入程序计数器，继续重复执行下 一条指令。如下图所示：", "analysis": "根据考纲书中的描述： 指令 是“能够被计算机识别并执行的二进制编码”， 它规定了计算机执行的 操作种类和数据地址，称为机器指令； 程序 是“指令的有序集合”，用以完成特定的计算任务或功能模块。 计算机执行指令的过程分为以下三个主要步骤： 取指令：控制器从内存中读取当前程序计数器（PC）所指向的指令； 分析指令：通过指令译码器对操作码进行分析，判断指令类型与操作数； 执行指令：根据指令内容由运算器或 I/O 接口执行操作，完成相应功能。 完成一条指令后， 程序计数器PC 更新到下一条指令地址， 继续循环， 直到遇 到“结束指令”为止。 图中流程正体现了“取→译→执行→判断是否结束→继续或结束”的典型执 行机制。", "sourceImageRefs": ["images/qb201/question-images/qfw-20260821-ch3/q147-1.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-001", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "001", "type": "选择题", "stem": "下列不属于冯·诺依曼体系结构的是（   ）。", "options": {"A": "程序和数据以二进制形式表示", "B": "计算机由运算器、控制器、存储器、输入设备和输出设备五个部分组成", "C": "程序和数据以同等地位存储到存储器中，按地址寻访", "D": "控制器以并行的方式处理数据"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书中关于冯·诺依曼体系结构的描述：\n在 EDVAC 中采用了‘存储程序’的思想，以此思想为基础的各类计算机统称为冯·诺\n依曼机。它的主要特点可以归结为以下几点。”\n具体包括：\n① 计算机由五个基本部分组成：运算器、控制器、存储器、输入设备和输出设备。\n② 程序和数据以同等地位存放在存储器中，并要按地址寻访。\n③ 程序和数据以二进制表示。\n因此：\nA、程序和数据以二进制形式表示 - 属于冯·诺依曼体系结构\nB、计算机由运算器、控制器、存储器、输入设备和输出设备五个部分组成 - 属于冯·诺\n依曼体系结构\nC、程序和数据以同等地位存储到存储器中，按地址寻访 - 属于冯·诺依曼体系结构\nD、控制器以并行的方式处理数据 —— 不属于冯·诺依曼体系结构的基本特征。冯·诺\n依曼体系强调“存储程序”和“顺序执行”，而不是并行处理机制。\n因此，答案为 D。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/001-p37.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-008"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-002", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "002", "type": "选择题", "stem": "冯·诺依曼体系的基本结构如下图，图中标识为“①”和“②”处是（   ）。", "options": {"A": "①数据流，②控制流", "B": "①控制流，②数据流", "C": "①输入流，②输出流", "D": "①输出流，②输入流"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，冯·诺依曼计算机的基本结构包括输入设备、存储器（内存储器和外存储\n器）、运算器、控制器和输出设备。计算机的基本工作原理是“存储程序”和“自动执\n行程序”，即程序和数据都存放在存储器中，CPU 依次从存储器中取出指令并执行。\n在冯·诺依曼体系结构中：\n数据流（①）表示数据在计算机系统中的传输路径，包括从输入设备传输到存储器、存\n储器到运算器、运算器到存储器，最终到输出设备的过程。\n控制流（②）是指控制器根据程序的指令，对各部件的操作进行协调和控制，确保计算\n机按照指令执行。\n因此，图中的 ① 代表数据流，② 代表控制流。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/002-p37.jpg", "images/qb201/question-images/qfw800-ch3-v201/002-p38.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw800-ch3-v201/002-p37.jpg"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-003", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "003", "type": "选择题", "stem": "计算机能按照人们的意图自动、高速地进行操作，是因为采用了（   ）。", "options": {"A": "程序存储在内存", "B": "高性能的CPU", "C": "高级语言", "D": "机器语言"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，计算机能够按照人们的意图自动、高速地进行操作，主要依赖于冯·诺依\n曼体系的“存储程序”概念，即程序和数据都存储在内存中，CPU 通过从内存中取指\n令并执行的方式来实现自动化计算。这种设计使计算机能够连续执行指令，而无需人为\n干预，从而实现自动化和高速运算。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/003-p38.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-002"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-004", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "004", "type": "选择题", "stem": "完整的计算机系统包括（   ）。", "options": {"A": "CPU和存储器", "B": "主机和实用程序", "C": "主机和外部设备", "D": "硬件系统和软件系统"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，完整的计算机系统由硬件系统和软件系统两部分组成。硬件系统包括主机\n（即 CPU、存储器、控制器和运算器）和外部设备（如输入设备、输出设备和存储设\n备），软件系统包括操作系统、应用软件等。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/004-p38.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-003"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-005", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "005", "type": "填空题", "stem": "没有软件的计算机称为_____。", "options": {}, "verifiedAnswer": "裸机", "sourceAnswer": "裸机", "analysis": "根据考纲书，计算机系统由硬件系统和软件系统组成，硬件是计算机的物理基础，而软\n件是计算机运行的指令集合。如果计算机仅由硬件组成，没有软件的支持，那么它无法\n执行任何有意义的任务，这种仅包含硬件、没有软件的计算机被称为“裸机”。裸机只\n能识别由 0 和 1 组成的机器码，用户难以直接使用，因此必须依赖软件来完成各种计\n算和操作。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/005-p38.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-006", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "006", "type": "填空题", "stem": "冯·诺依曼体系结构中，程序和数据以同等地位存放在存储器中，并按_____寻访。", "options": {}, "verifiedAnswer": "地址", "sourceAnswer": "地址", "analysis": "原书答案栏印为 D，但原题为填空题。原书解析写的是“按地址寻访”，答案待核查。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/006-p39.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-007", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "007", "type": "填空题", "stem": "计算机由5 个部分组成，分别是_____、_____、_____、_____和_____。", "options": {}, "verifiedAnswer": "运算器、控制器、存储器、输入设备、输出设备", "sourceAnswer": "运算器、控制器、存储器、输入设备、输出设备", "analysis": "根据考纲书，计算机的基本组成部分包括运算器、控制器、存储器、输入设备和输出设\n备，这是冯·诺依曼计算机体系结构的核心内容。\n① 运算器：用于执行算术和逻辑运算。\n② 控制器：负责解释和执行指令，控制计算机各部件的协调运行。\n③ 存储器：用于存储程序和数据，包括内存（RAM）和外存（如硬盘、U 盘等）。\n④ 输入设备：用于将数据和指令输入计算机，如键盘、鼠标、扫描仪等。\n⑤ 输出设备：用于将计算结果或信息输出，如显示器、打印机、音响等。\n这五大组成部分共同协作，使计算机能够接收输入、存储数据、进行计算并输出结果，\n完成各类计算任务。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/007-p39.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-008", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "008", "type": "填空题", "stem": "冯·诺依曼计算机的硬件系统由五大部分组成，其中整个计算机的指挥中心是_____。", "options": {}, "verifiedAnswer": "控制器", "sourceAnswer": "控制器", "analysis": "根据考纲书，冯·诺依曼计算机的硬件系统由运算器、控制器、存储器、输入设备和输出\n设备五部分组成。其中，控制器（Control Unit, CU）是整个计算机的指挥中心，它负\n责从存储器中取出指令并加以分析，向计算机各部件发出控制信号，使计算机按照程序\n规定的步骤自动运行。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/008-p39.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-009", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "009", "type": "选择题", "stem": "计算机的主机指的是（   ）。", "options": {"A": "计算机的主机箱", "B": "CPU和内存储器", "C": "运算器和控制器", "D": "运算器和输入输出设备"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，计算机的主机是指计算机的核心部分，通常包括CPU（中央处理器）和\n内存储器。其中，CPU 由运算器和控制器组成，负责数据处理和程序控制；内存储器\n用于存放正在执行的程序和数据。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/009-p39.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-20261014-189"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-010", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "18 冯·诺依曼体系结构", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "010", "type": "判断题", "stem": "在微型计算机系统中，外部设备指的是安装在主机箱外面的设备。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，外部设备是计算机系统的重要组成部分，用于输入数据、输出结果或进行\n数据存储，但它并不等同于“安装在主机箱外面的设备”。外部设备包括输入设备、输\n出设备和外存储器，例如键盘、鼠标、显示器、打印机、硬盘、U 盘等。\n其中，外存储器（如硬盘、固态硬盘）虽然通常安装在主机箱内部，但仍属于外部设备，\n因为它不是计算机的核心处理单元，而是用于数据存储。因此，以“安装在主机箱外面”\n作为判断标准是不准确的。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/010-p40.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-010"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-011", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "011", "type": "选择题", "stem": "下列关于计算机指令的说法中，错误的是（   ）。", "options": {"A": "指令与硬件有关", "B": "指令一般包括操作码和地址码两部分", "C": "指令是指示计算机执行某种操作的命令", "D": "指令必须经过编译后才能被计算机理解和执行"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，计算机指令是计算机执行操作的基本单位，由操作码和地址码两部分组成。\n指令直接由计算机硬件执行，因此与硬件密切相关。计算机执行指令时，不需要经过编\n译，而是直接由 CPU 识别和执行。编译是高级语言程序转换为机器语言的过程，而指\n令本身就是计算机可以直接执行的机器语言，因此该说法错误。\n综上，正确答案是 D。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/011-p40.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-011"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-012", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "012", "type": "填空题", "stem": "计算机的工作过程实际上是快速地_____的过程。", "options": {}, "verifiedAnswer": "执行指令或执行程序", "sourceAnswer": "执行指令或执行程序", "analysis": "根据考纲书，计算机的工作过程本质上是按照程序的指令自动、快速地执行运算和处理\n数据的过程。计算机依靠存储程序和自动执行程序的机制，从存储器中依次取出指令，\n并由 CPU 进行解码和执行，完成各种计算和控制任务。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/012-p40.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-013", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "013", "type": "填空题", "stem": "通常一条指令由_____和_____组成。", "options": {}, "verifiedAnswer": "操作码，地址码", "sourceAnswer": "操作码，地址码", "analysis": "根据考纲书，计算机中的指令是计算机执行操作的基本单位，通常由操作码和地址码两\n部分组成。\n操作码：用于指定 CPU 需要执行的操作类型，如加法、减法、存储、取数等。\n地址码：用于指示操作数的位置，即告诉 CPU 从哪里获取或存储数据。\n因此，指令格式通常为：操作码+地址码。其中，操作码定义了执行的操作类型，而地\n址码提供了数据存放的具体位置。\n有些指令可以没有操作码，例如停机指令。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/013-p40.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-014", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "014", "type": "选择题", "stem": "计算机的指令集合称为（   ）。", "options": {"A": "机器语言", "B": "高级语言", "C": "程序", "D": "软件"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，计算机的指令集合指的是计算机能够直接识别和执行的一组二进制指令，\n这些指令由操作码和地址码组成，统称为机器语言。机器语言是计算机硬件能够直接执\n行的最低级语言，不需要翻译或编译。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/014-p41.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-20261014-197"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-015", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "015", "type": "选择题", "stem": "以下（   ）不属于指令系统的指令。", "options": {"A": "数据传送指令", "B": "数据加密指令", "C": "数据处理指令", "D": "程序控制指令"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，计算机的指令系统是计算机 CPU 能够执行的全部指令的集合。不同计算\n机的指令系统包含的指令种类和数量可能有所不同，但一般包括以下几种类型的指令：\n① 数据传送型指令：用于在存储器之间、寄存器之间，以及存储器和寄存器之间传输\n数据。\n② 数据处理型指令：用于执行算术运算（加、减、乘、除等）和逻辑运算（与、或、\n非等）。\n③ 程序控制型指令：用于控制程序执行流程，例如跳转、循环、调用子程序等。\n④ 输入和输出型指令：用于实现主机与外部设备之间的数据交换，如从键盘输入数据、\n将数据输出到显示器或打印机等。\n⑤ 硬件控制型指令：用于控制计算机的硬件运行，如系统初始化、关机等操作。\n这些指令类别共同构成了计算机的基本指令集，使得计算机能够执行各种任务，从基本\n的数据存储与运算到复杂的程序控制和外部设备管理。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/015-p41.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-015"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-016", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "016", "type": "填空题", "stem": "如下图所示，将不同指令的各个步骤通过多个硬件处理单元进行重叠操作，从而实现几 条指令的并行处理，以加速程序运行过程的技术称为_____技术。", "options": {}, "verifiedAnswer": "流水线或指令流水线", "sourceAnswer": "流水线或指令流水线", "analysis": "根据考纲书，图示的技术属于流水线或指令流水线技术。流水线技术是一种提高计算机\n处理速度的方法，它通过将不同指令的各个步骤（如取指令、译码、执行等）分阶段处\n理，并由多个硬件单元并行执行多个指令的不同阶段，从而提高 CPU 的执行效率。举\n例来说，当一条指令处于执行阶段时，下一条指令可以同时进行译码，再下一条指令可\n以取指令，形成多条指令的并行处理，从而提高计算机的执行效率。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/016-p41.jpg", "images/qb201/question-images/qfw800-ch3-v201/016-p42.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw800-ch3-v201/016-p41.jpg"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-017", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "017", "type": "填空题", "stem": "指令的执行过程分为3 个步骤：取指令、分析指令和_____指令。", "options": {}, "verifiedAnswer": "执行指令", "sourceAnswer": "执行指令", "analysis": "根据考纲书，计算机执行指令的过程通常分为三个基本步骤：\n① 取指令：CPU 从存储器（内存）中取出下一条要执行的指令，并将其存入指令寄存\n器。\n② 分析指令：CPU 解析指令的操作码，确定要执行的操作类型，并获取指令所需的操\n作数地址或数据。\n③ 执行指令：CPU 根据指令的功能要求，完成运算、数据传输、逻辑判断等操作，最\n终得到计算结果。\n因此，正确答案是：执行指令。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/017-p42.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-018", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "19 计算机的工作原理", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "018", "type": "判断题", "stem": "下图对计算机中指令的执行过程的描述是正确的。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，计算机的指令执行过程通常遵循取指令-分析指令-执行指令的基本流程，\n并且包含程序控制机制，如判断是否为结束指令。\n从图示来看，该流程正确描述了计算机指令的执行过程：\n①  取指令\n②  分析指令\n③  判断是否为结束指令：\n如果是结束指令，则程序终止，进入“结果”状态。\n如果不是，则执行该指令，执行完成后回到“取指令”步骤，继续下一条指令。\n这一流程符合计算机冯·诺依曼体系的基本工作原理，因此，该图对计算机指令的执行\n过程描述是正确的。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/018-p42.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw800-ch3-v201/018-p42.jpg"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-019", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "019", "type": "选择题", "stem": "计算机中，中央处理器CPU 由哪两部分组成（   ）。", "options": {"A": "控制器、运算器", "B": "控制器、存储器", "C": "控制器、寄存器", "D": "寄存器、存储器"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，计算机的中央处理器（CPU）是计算机的核心部件，主要由控制器（CU）\n和运算器（ALU）两部分组成。\n① 控制器：负责从存储器中取指令、分析指令，并协调各部件工作，确保程序按顺序\n执行。\n② 运算器：负责执行算术运算（如加法、减法等）和逻辑运算（如与、或、非等）。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/019-p43.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-020"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-020", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "020", "type": "判断题", "stem": "微型计算机中，运算器的主要功能是分析指令并译码。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，运算器（Arithmetic and Logic Unit, ALU）的主要功能是执行算术和\n逻辑运算，如加、减、乘、除、与、或、非等操作，而指令的分析和译码是控制器（Control\nUnit, CU）的职责。\n在计算机的基本工作流程中：\n① 控制器 负责取指令、分析指令，并向各部件发送控制信号。\n② 运算器 负责执行指令，即对数据进行运算，包括算术运算和逻辑判断。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/020-p43.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-CH1FINAL-091"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-021", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "021", "type": "选择题", "stem": "一般来说，CPU 的（   ）越高，运算速度也就越快。", "options": {"A": "位数", "B": "主频", "C": "带宽", "D": "字长"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，CPU 的主频（Clock Speed）指的是 CPU 每秒钟执行的时钟频率，通\n常以 MHz（百万次/秒）或 GHz（十亿次/秒）为单位。一般来说，主频越高，CPU 在\n单位时间内可以执行的指令就越多，因此运算速度也就越快。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/021-p43.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-025"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-022", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "022", "type": "选择题", "stem": "CPU 的主频是指CPU 的（   ）。", "options": {"A": "无线电频率", "B": "电压频率", "C": "时钟频率", "D": "电流频率"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "见上题。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/022-p44.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-026"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-023", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "023", "type": "选择题", "stem": "Cache 可以提高计算机的性能，这是因为（   ）。", "options": {"A": "提高了CPU的倍频", "B": "提高了CPU的主频", "C": "提高了RAM的容量", "D": "缩短了CPU访问数据的时间"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，Cache（高速缓存）的主要作用是缩短 CPU 访问数据的时间，从而提高\n计算机的整体性能。Cache 介于 CPU 和主存（RAM）之间，存储最近使用或即将使\n用的数据，使 CPU 在需要数据时可以更快地从 Cache 获取，而不必等待较慢的\nRAM 访问。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/023-p44.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-028"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-024", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "024", "type": "选择题", "stem": "CPU 中的L1、L2 和L3 Cache 的主要区别在于（   ）。", "options": {"A": "它们的容量大小不同，L1 Cache最大，L3 Cache最小", "B": "它们的运行频率不同，L1 Cache最慢，L3 Cache最快", "C": "L1 Cache和L2 Cache是每个核心独立的，而L3 Cache是多个核心共享的", "D": "只有L3 Cache可以减少CPU从内存读取数据的等待时间"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，CPU 中的 L1、L2 和 L3 Cache 主要用于加速数据访问，它们之间的\n主要区别在于层级结构和共享方式：\n① L1 Cache（一级缓存）：速度最快，容量最小（通常 32KB - 128KB），每个 CPU\n核心独立拥有。\n② L2 Cache（二级缓存）：比 L1 稍慢，容量更大（通常 256KB - 1MB），通常每个\n核心独立拥有，但在部分架构中可以被多个核心共享。\n③ L3 Cache（三级缓存）：速度比 L2 缓慢，但容量更大（通常 2MB - 64MB），多\n个核心共享，用于进一步减少 CPU 访问内存的时间。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/024-p44.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-029"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-025", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "025", "type": "判断题", "stem": "与CPU 封装在一起的cache 可看作主存的延伸，与主存统一编址，接受CPU 的访问， 但速度比主存快。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，CPU 内部封装的 Cache（高速缓存） 并不属于主存（RAM）的一部分，\n而是独立的存储单元，它与主存不统一编址，且通常由 CPU 内部控制，不直接对外部\n设备开放访问。Cache 的作用是加速数据访问，减少 CPU 直接访问主存的延迟，但\n它并不等同于主存的扩展。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/025-p44.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-030"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-026", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "026", "type": "选择题", "stem": "在计算机中，作为一个整体参与运算、处理和传送的一串二进制数称为（   ），其位数 称为（   ）。", "options": {"A": "字，字长", "B": "字长，字", "C": "字节，字长", "D": "字长，字节"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，计算机中的“字”是指作为一个整体参与运算、处理和传送的一串二进制\n数，而该串二进制数的位数被称为字长。\n① 字：计算机处理数据时，CPU 一次存取、加工和传送的数据单位称为“字”。\n② 字长：计算机一次能处理的二进制位数，即 CPU 一次操作的位宽，如 8 位、16\n位、32 位或 64 位。字长越长，CPU 的精度越高，计算能力也越强。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/026-p45.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-031"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-027", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "027", "type": "选择题", "stem": "CPU 的字长（   ）通用寄存器的位数。", "options": {"A": "小于", "B": "等于", "C": "大于", "D": "不等于"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，CPU 的字长通常指的是 CPU 一次能处理的二进制数据位数，而通用寄\n存器的位数通常与 CPU 的字长相同，因为通用寄存器用于存储 CPU 处理的数据和\n指令操作数。如果 CPU 的字长是 32 位，那么其通用寄存器的位数通常也是 32 位；\n如果是 64 位 CPU，则寄存器的位数也是 64 位。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/027-p45.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-032"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-028", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "028", "type": "选择题", "stem": "CPU 的字长决定了（   ）。", "options": {"A": "CPU的主频", "B": "CPU的能耗", "C": "CPU处理数据的精度", "D": "CPU的功能"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，CPU 的字长指的是 CPU 一次能够处理的二进制数据的位数，通常以 8\n位、16 位、32 位或 64 位表示。字长越长，CPU 在计算过程中能处理的数据范围越\n大，数据精度也越高。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/028-p45.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-033"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-029", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "029", "type": "选择题", "stem": "“64 位微机”中的64 位指的是（   ）。", "options": {"A": "CPU型号", "B": "存储单位", "C": "内存容量", "D": "机器字长"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，“64 位微机”中的 64 位 指的是CPU 的字长，即 CPU 一次能处理的\n二进制数据的位数。64 位 CPU 能够一次处理 64 位二进制数据，具有更高的数据吞\n吐能力，同时也支持更大的内存寻址空间（可寻址 16EB 的内存）。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/029-p46.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-034"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-030", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "030", "type": "填空题", "stem": "目前手机、个人电脑、服务器等设备使用的_____广泛采用多核技术，对提高处理速度 具有显著作用。", "options": {}, "verifiedAnswer": "CPU 或中央处理器或微处理器", "sourceAnswer": "CPU 或中央处理器或微处理器", "analysis": "考纲书上的原话，记住结论即可。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/030-p46.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-031", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "031", "type": "判断题", "stem": "睿频技术允许CPU 在重任务时提高主频，而在轻任务时降低主频以节能。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，睿频技术（Turbo Boost） 是现代 CPU 采用的一种动态频率调节技术，\n它能够根据任务的负载情况自动调整 CPU 的主频，以实现性能和功耗的平衡。\n① 重任务时提高主频：当 CPU 运行高强度任务（如游戏、视频编辑、大规模计算）\n时，睿频技术会自动提升 CPU 频率，以提高计算速度。\n② 轻任务时降低主频：当 CPU 处于低负载状态（如浏览网页、编辑文档）时，睿频\n技术会降低 CPU 频率，以减少功耗并降低发热量，从而延长电池续航（对移动设备尤\n其重要）。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/031-p46.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-036"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-032", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "032", "type": "判断题", "stem": "QPI 总线的带宽越高，意味着CPU 的数据处理能力越强。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，QPI（QuickPath Interconnect）总线 是 Intel 处理器架构中的高速点\n对点互连技术，用于CPU 与内存、I/O 设备以及其他 CPU 之间的数据传输。QPI 总\n线的带宽越高，意味着数据在 CPU 和其他组件之间的传输速度更快，从而提高 CPU\n的数据处理能力。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/032-p46.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-037"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-033", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "033", "type": "判断题", "stem": "多线程机制能减少CPU 的闲置时间，提高CPU 的运行效率。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，多线程机制（Multithreading） 是 CPU 通过同时处理多个线程 来提\n高计算效率的一种技术。多线程机制的核心目标是减少 CPU 的空闲时间，充分利用计\n算资源，从而提高 CPU 的运行效率。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/033-p46.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-038"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-034", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "034", "type": "选择题", "stem": "下列选项中，不属于智能处理器特征的是（   ）。", "options": {"A": "采用睿频加速技术，按负载提升主频，高效节能", "B": "采用超线程技术，提升CPU的并行处理能力", "C": "集成高清显卡，大幅提升3D性能", "D": "集成专业声卡，大幅提升声音质量"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，智能处理器 主要具备以下特征：\nA、睿频加速技术（A 选项）：\n根据 CPU 负载动态调整主频，在高负载时提升性能，低负载时降低功耗，提高能效。\nB、超线程技术（B 选项）：\n让 CPU 的每个物理核心能够同时运行多个线程，提高 CPU 的并行计算能力，提升处\n理效率。\nC、集成高清显卡（C 选项）：\n现代 CPU 逐渐集成 GPU（图形处理单元），以提高 3D 渲染和多媒体处理能力，如\nIntel 核显和 AMD APU。\n声卡（D 选项）一般集成主板上，并不会集成在CPU 内部。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/034-p47.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-039"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-035", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "035", "type": "选择题", "stem": "下列不属于国产芯片的是（   ）。", "options": {"A": "麒麟", "B": "酷睿", "C": "龙芯", "D": "申威"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，国产芯片 是指由中国自主研发和生产的 CPU 芯片，代表着中国在芯片\n领域的自主创新能力。\n国产芯片：\nA、麒麟：华为海思研发的 ARM 架构处理器，广泛应用于华为手机。\nC、龙芯（Loongson）：中国科学院计算技术研究所研制的自主指令集 CPU，主要用\n于国产 PC 和服务器。\nD、申威：用于中国国产超级计算机“神威·太湖之光”，采用自主研发的架构。\nB、酷睿（Core）是Intel（英特尔）公司研发的 x86 架构处理器，广泛应用于全球 PC\n和服务器市场，因此不属于国产芯片。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/035-p47.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-043"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-036", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "20 CPU", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "036", "type": "选择题", "stem": "关于龙芯CPU 的描述，以下哪项是错误的（   ）。", "options": {"A": "龙芯CPU是基于RISC架构", "B": "龙芯CPU主要应用于个人计算机", "C": "龙芯CPU具有自主知识产权", "D": "龙芯处理器采用简单指令集"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，龙芯（Loongson）CPU 是中国自主研发的处理器，具有自主知识产权，\n并基于 RISC（精简指令集计算机）架构。虽然龙芯 CPU 可以用于个人计算机，但它\n的主要应用领域包括超级计算机、国产服务器、嵌入式系统和工业控制等，并非主要针\n对个人 PC 市场。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/036-p47.jpg", "images/qb201/question-images/qfw800-ch3-v201/036-p48.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-044"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-037", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "037", "type": "填空题", "stem": "内存是CPU 能够_____访问的存储器，用于存放正在运行的程序和数据。", "options": {}, "verifiedAnswer": "直接", "sourceAnswer": "直接", "analysis": "根据考纲书，内存（RAM，随机存取存储器） 是 CPU 能够直接 访问的存储器，用\n于存放正在运行的程序和数据。由于内存的访问速度比外存（如硬盘）快得多，CPU 直\n接从内存中读取指令和数据，以提高计算效率。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/037-p48.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-038", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "038", "type": "判断题", "stem": "程序必须调入内存运行。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，计算机采用冯·诺依曼体系结构，其中程序和数据必须存储在内存中，CPU\n才能直接访问。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/038-p48.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-046"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-039", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "039", "type": "判断题", "stem": "打开一个Word 文档，是指把该文档从磁盘调入内存，并在窗口的工作区显示其内容。 （   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "见上题和第038 题的解析。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/039-p48.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-047"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-040", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "040", "type": "选择题", "stem": "内存储器是CPU 能直接访问的存储器，下列哪一个不属于内存储器（   ）。", "options": {"A": "随机访问存储器", "B": "只读存储器", "C": "高速缓冲存储器", "D": "优盘存储器"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，内存储器是 CPU 能直接访问的存储器，用于存储正在运行的程序和数据，\n常见的内存储器包括：\nA、随机访问存储器（RAM）：属于内存，CPU 可直接访问，存储临时数据。\nB、只读存储器（ROM）：属于内存，存储固化的系统程序，如 BIOS。\nC、高速缓冲存储器（Cache）：属于 CPU 内部的缓存，用于加速数据访问。\nD、优盘存储器（U 盘）属于外部存储设备（外存），数据需要先从 U 盘读入内存，\nCPU 才能访问，因此 不属于内存储器。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/040-p48.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-050"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-041", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "041", "type": "选择题", "stem": "下列存储器中，（   ）的特点是只能读出原有内容，不能由用户再写入新内容。", "options": {"A": "RAM", "B": "ROM", "C": "DRAM", "D": "SRAM"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，只读存储器（ROM，Read-Only Memory） 是一种只能读出原有内容，\n而不能由用户写入新内容的存储器。ROM 在出厂时就已经写入了固定的程序或数据，\n用户无法随意修改，主要用于存储 BIOS、固件等系统级程序。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/041-p49.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-051"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-042", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "042", "type": "选择题", "stem": "引导系统开机自检的程序存放在（   ）。", "options": {"A": "硬盘", "B": "ROM", "C": "内存", "D": "磁盘"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，引导系统开机自检（POST，Power-On Self Test）的程序存放在 ROM\n（只读存储器）中。ROM 中存储的 BIOS（基本输入输出系统）负责在计算机开机时\n执行硬件自检（POST），并引导操作系统启动。由于 ROM 具有断电不丢失数据的特\n性，因此适合存放开机时必须执行的固件程序。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/042-p49.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-052"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-043", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "043", "type": "选择题", "stem": "微型计算机系统中的内存条指的是（   ）。", "options": {"A": "ROM", "B": "RAM", "C": "CD-ROM", "D": "CMOS"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，内存条指的是RAM（随机存取存储器），如第044 题的图中所示的设备。\nRAM 中用于存放正在运行的程序和数据，CPU 可以直接访问 RAM。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/043-p49.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-053"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-044", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "044", "type": "选择题", "stem": "以下安装在计算机内部主板插槽上的部件是（   ）。", "options": {"A": "静态内存", "B": "动态内存", "C": "高速缓存", "D": "FLASH缓存"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "见上题。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/044-p49.jpg", "images/qb201/question-images/qfw800-ch3-v201/044-p50.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw800-ch3-v201/044-p49.jpg"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-045", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "045", "type": "填空题", "stem": "RAM 主要的性能指标有两个： _____和_____。", "options": {}, "verifiedAnswer": "存储容量，存取速度", "sourceAnswer": "存储容量，存取速度", "analysis": "根据考纲书，RAM 的性能主要取决于两个关键指标：\n① 存储容量：指 RAM 可以存储的数据总量，通常以 GB 为单位，如 8GB、16GB、\n32GB。存储容量越大，系统可以运行的程序和数据就越多，性能更好。\n② 存取速度：指 CPU 访问 RAM 读取或写入数据的速度，通常由内存频率（MHz）\n和延迟决定，例如 DDR4 3200MHz、DDR5 4800MHz。存取速度越快，数据交换效\n率越高，系统运行更流畅。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/045-p50.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-046", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "046", "type": "选择题", "stem": "微型计算机内存容量的基本单位是（   ）。", "options": {"A": "字符", "B": "字节", "C": "二进制位", "D": "扇区"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，微型计算机内存容量的基本单位是“字节”（Byte，B）。在计算机存储体\n系中，字节（B）是最基本的数据存储单位，通常用于衡量内存、硬盘等存储设备的容\n量。\n其它选项：\nA、字符：字符是数据的一种表示方式，而不是存储容量的基本单位；\nC、二进制位（bit）：虽然计算机数据存储的最小单位是 bit（位），但内存容量通常以\n字节（Byte） 作为计算单位，1 字节 = 8 位；\nD、扇区：扇区是硬盘等存储设备上的数据存储单位，通常 1 扇区 = 512 字节。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/046-p50.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-056"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-047", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "047", "type": "填空题", "stem": "为了能存取内存的数据，每个内存单元必须有一个唯一的编号，称为_____。", "options": {}, "verifiedAnswer": "地址或内存地址", "sourceAnswer": "地址或内存地址", "analysis": "根据考纲书，为了能存取内存的数据，每个内存单元必须有一个唯一的编号，称为地址\n或内存地址。地址是计算机存储器中每个存储单元的唯一标识，CPU 通过内存地址来\n读取或写入数据。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/047-p50.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-048", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "048", "type": "填空题", "stem": "在程序运行时，可以根据_____直接访问随机文件结构中的某一特定记录。", "options": {}, "verifiedAnswer": "地址或主键", "sourceAnswer": "地址或主键", "analysis": "见上题。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/048-p50.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-049", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "049", "type": "选择题", "stem": "为了解决用户要求存储容量大、速度快和成本低之间的矛盾，目前计算机采用高速缓冲 存储器（cache）、内存储器和外存储器的体系结构，该体系结构是（   ）。", "options": {"A": "多级存储结构", "B": "固态硬盘阵列", "C": "机械硬盘阵列", "D": "多级流水线存储结构"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，为了平衡存储容量、访问速度和成本之间的矛盾，计算机采用多级存储结\n构，即通过高速缓冲存储器（Cache）、内存储器（RAM）和外存储器（硬盘、固态硬\n盘等）组成的层次化存储系统。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/049-p51.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-059"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-050", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "050", "type": "选择题", "stem": "计算机的多级存储器体系结构中，Cache 的作用是（   ）。", "options": {"A": "长期存储数据", "B": "存放当前使用最频繁的指令和数据", "C": "存放启动程序", "D": "作为CPU的主要存储单元"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，在计算机的多级存储器体系结构中，Cache（高速缓存）主要用于存放当\n前使用最频繁的指令和数据，以提高 CPU 访问速度，减少访问内存（RAM）的时间。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/050-p51.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-060"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-051", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "051", "type": "选择题", "stem": "在微型计算机系统常用的存储器中，读写速度最快的是（   ）。", "options": {"A": "硬盘", "B": "U盘", "C": "光盘", "D": "内存"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，在微型计算机系统常用的存储器中，内存（RAM） 的读写速度最快，远\n远快于硬盘、U 盘和光盘。\n存储器读写速度从快到慢：\n① CPU 寄存器（最快，纳秒级）\n② Cache（高速缓存）（纳秒级，比 RAM 快）\n③ 内存（RAM）（微秒级，远快于硬盘和外部存储设备）\n④ 固态硬盘（SSD）（比机械硬盘快，但比 RAM 慢）\n⑤ 机械硬盘（HDD）（毫秒级）\n⑥ U 盘、光盘等外部存储设备（速度最慢）", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/051-p51.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-062"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-052", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "21 内存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "052", "type": "选择题", "stem": "计算机机存储体系由多级存储部件构成，下列部件存储速度最快的是（   ）。", "options": {"A": "硬盘", "B": "寄存器", "C": "RAM", "D": "cache"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "见上题。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/052-p52.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-063"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-053", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "053", "type": "选择题", "stem": "下列存储设备中，存取速度最快的是（   ）。", "options": {"A": "DVD-RW", "B": "FD", "C": "HD", "D": "SSD"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，存储设备的存取速度由其存储介质和读写技术决定。\nDVD-RW（A）是一种光存储介质，采用激光读取，存取速度较慢。\nFD（B，即软盘）采用磁介质存储，数据传输速率极低，存取速度最慢。\nHD（C，即传统机械硬盘）使用磁盘旋转和磁头读写，虽然比软盘快，但仍远逊于固态\n硬盘。\nSSD（D，即固态硬盘）采用闪存技术，没有机械部件，具有更快的存取速度和数据吞\n吐能力，是四者中存取速度最快的存储设备。外存中SSD 最快，记住这个结论。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/053-p52.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-066"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-054", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "054", "type": "选择题", "stem": "存储设备和存储介质没有封装在一起的存储技术是（   ）。", "options": {"A": "U盘", "B": "机械硬盘", "C": "固态硬盘", "D": "光盘"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "U 盘、机械硬盘和固态硬盘都属于存储设备与存储介质封装在一起的存储形式，即存\n储介质与控制电路、接口电路集成为一个整体，用户无法分离其内部存储介质。\n而光盘属于可移动存储介质，其数据存储在独立的光盘片上，需要配合光驱等设备读取，\n存储设备（光驱）和存储介质（光盘）是分离的，并未封装在一起。\n因此，答案为 D。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/054-p52.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-055", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "055", "type": "选择题", "stem": "磁盘驱动器属于（   ）设备。", "options": {"A": "输入", "B": "输出", "C": "输入和输出", "D": "以上均不是"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，磁盘驱动器（如硬盘、U 盘、光盘驱动器等）既能接收数据存入磁盘（此\n时作为输出设备），又能读取磁盘中的数据输出给计算机（此时作为输入设备），因此它\n既是输入设备，又是输出设备。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/055-p53.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-20261014-192"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-056", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "056", "type": "选择题", "stem": "和机械硬盘相比，固态硬盘的主要优点是（   ）。", "options": {"A": "容量大", "B": "读写速度快", "C": "价格便宜", "D": "使用寿命长"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，固态硬盘（SSD）采用闪存技术，没有机械部件，因此比传统机械硬盘（HDD）\n具有更快的读写速度，这是其主要优势。容量、价格和使用寿命上，SSD 都比不上传统\n的机械硬盘。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/056-p53.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-067"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-057", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "057", "type": "选择题", "stem": "转速是硬盘盘片每分钟转动的圈数，单位是（   ）。转速越快，数据存取速度越快。", "options": {"A": "dpi", "B": "rpm", "C": "ppm", "D": "bps"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "转速是指硬盘盘片每分钟旋转的圈数，其单位为 rpm，表示“每分钟转数”。\n在硬盘性能指标中，转速越高，磁头单位时间内经过的数据区域越多，平均寻道时间和\n等待时间越短，因此数据存取速度越快。\n其它选项分析：\nA、dpi（dots per inch）\n表示每英寸点数，常用于打印分辨率或图像分辨率，不是硬盘转速单位。\nC、ppm（pages per minute）\n表示每分钟页数，多用于打印机速度指标。\nD、bps（bits per second）\n表示每秒比特数，是数据传输速率和带宽的单位。\n因此，答案为 B。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/057-p53.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-058", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "058", "type": "选择题", "stem": "光盘驱动器通过激光束来读取光盘上的数据时，光学头与光盘（   ）。", "options": {"A": "直接接触", "B": "不直接接触", "C": "播放VCD时接触", "D": "有时接触有时不接触"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，光盘驱动器在读取光盘数据时，光学头通过激光束照射光盘表面的凹坑和\n反射区域来读取数据，而不会与光盘直接接触。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/058-p54.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-069"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-059", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "22 外存储器", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "059", "type": "填空题", "stem": "在计算机上用于衡量光盘驱动器传输数据速率的指标称为_____。", "options": {}, "verifiedAnswer": "倍速", "sourceAnswer": "倍速", "analysis": "根据考纲书，衡量光盘驱动器传输数据速率的指标称为倍速（X）。CD 的 1× = 150 KB/s，DVD 的 1× = 1350 KB/s。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/059-p54.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-060", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "23 输入设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "060", "type": "判断题", "stem": "输入设备接受用户输入的原始数据和程序，并将它们转换成计算机可以识别的形式；输 出设备用于将计算机处理的结果转变为用户可接受的形式。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，输入设备的主要功能是接受用户输入的原始数据和程序，并将其转换为计\n算机可以识别的二进制数据存入内存，例如键盘、鼠标、扫描仪等。\n输出设备的功能是将计算机处理的结果转换为用户可理解的形式并输出，例如显示器、\n打印机、音响等。\n因此，题干的描述是正确的。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/060-p54.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-074"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-061", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "23 输入设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "061", "type": "填空题", "stem": "常用的输入设备_____、鼠标、触摸屏、扫描仪、话筒等。", "options": {}, "verifiedAnswer": "键盘", "sourceAnswer": "键盘", "analysis": "见上题。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/061-p54.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-062", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "23 输入设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "062", "type": "判断题", "stem": "在多媒体扩展设备中，触摸屏是一种坐标定位装置，属于输出设备。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，触摸屏一般特指其作为坐标定位装置的“外屏”，属于输入设备，而不是\n输出设备。它通过手指或触控笔的触摸来接收用户输入，将触摸位置转换为计算机可以\n识别的坐标信息，从而进行交互。\n如果题目中的“触摸屏”包含了用于显示内容的“内屏”，那么内屏属于输出设备，而\n外屏属于输入设备。从这个角度上来说，可以说包含了“内屏”和“外屏”的触摸屏（显\n示触摸屏）既属于输入设备，又属于输出设备。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/062-p54.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-076"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-063", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "063", "type": "填空题", "stem": "常用的输出设备是显示器、_____、绘图仪、音响等。", "options": {}, "verifiedAnswer": "打印机", "sourceAnswer": "打印机", "analysis": "见本章第060 题的解析。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/063-p55.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-064", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "064", "type": "选择题", "stem": "关于显示器的说法，错误的是（   ）。", "options": {"A": "颜色位数越多越好", "B": "显示器越大越好", "C": "分辨率越高越好", "D": "刷新频率越高越好"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，显示器的性能通常由颜色位数、分辨率和刷新频率等指标决定，但显示器\n的尺寸并非越大越好，而是要根据使用需求、分辨率和观看距离来选择合适的尺寸。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/064-p55.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-20261014-215"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-065", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "065", "type": "选择题", "stem": "计算机显示器采用（   ）模型显示颜色。", "options": {"A": "HSL", "B": "RGB", "C": "CMYK", "D": "LAB"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，计算机显示器采用 RGB（红、绿、蓝）颜色模型来显示颜色。RGB 是一\n种加色模型，通过不同亮度的红、绿、蓝三原色光的组合来呈现各种颜色，广泛应用于\n显示设备，如计算机显示器、电视屏幕和手机屏幕。\n值得注意的是，C 选项中的CMYK（青、品红、黄、黑）是用于印刷的颜色模型，而非\n计算机显示器使用的颜色模型。\nHSL（色相、饱和度、亮度）是一种颜色表示方法，主要用于图像处理和设计软件中，\n不是计算机显示器的基础颜色模型。LAB 颜色模型是一种设备无关的颜色表示方式，\n主要用于色彩校正和高精度色彩处理。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/065-p55.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-080"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-066", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "066", "type": "选择题", "stem": "标准VGA 显示器中使用的三基色是（   ）。", "options": {"A": "红色", "B": "紫色", "C": "绿色", "D": "蓝色"}, "verifiedAnswer": "ACD", "sourceAnswer": "ACD", "analysis": "见上题。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/066-p55.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-067", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "067", "type": "判断题", "stem": "要使用显示器“真彩色”的显示效果，计算机显示适配器的颜色质量属性应该至少设置 为24 位。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，真彩色通常指 24 位颜色深度，即每个像素由 红、绿、蓝（RGB）三种\n颜色各 8 位（共 24 位）组成，可以表示 2²΀ = 16777216（约 1677 万）种颜色。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/067-p56.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-082"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-068", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "068", "type": "填空题", "stem": "打印机采用的颜色模式是C（青）、M（品红）、Y（   ）和K（黑）。", "options": {}, "verifiedAnswer": "黄", "sourceAnswer": "黄", "analysis": "见第065 题的解析。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/068-p56.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-069", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "069", "type": "填空题", "stem": "速度快、印字质量好、噪音低的打印机类型是______。", "options": {}, "verifiedAnswer": "激光打印机", "sourceAnswer": "激光打印机", "analysis": "根据考纲书，激光打印机具有速度快、印字质量好、噪音低的特点。它采用静电成像技\n术和激光扫描技术，利用碳粉成像并通过高温定影，使打印效果清晰细腻。同时，由于\n激光打印机没有撞击式打印头（针式打印机），其工作过程噪音较低，因此广泛应用于\n办公环境。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/069-p56.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-070", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "070", "type": "选择题", "stem": "（   ）以计算机模型文件为基础，运用粉末状塑料或金属等可黏合材料，通过逐层打 印的方式来构造物体的技术。", "options": {"A": "针式打印机", "B": "喷墨打印机", "C": "激光打印机", "D": "3D打印机"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，3D 打印机是一种以计算机模型文件为基础，使用粉末状塑料、金属或其\n他可黏合材料，通过逐层打印的方式构造物体的技术。这种技术属于增材制造，广泛应\n用于工业制造、医疗、建筑、艺术等领域。\nA（针式打印机）错误，针式打印机采用撞击式打印技术，主要用于打印发票等场景。\nB（喷墨打印机）错误，喷墨打印机通过喷射墨滴来打印文本和图像，无法进行三维成\n型。\nC（激光打印机）错误，激光打印机利用静电成像原理进行高速高质量的二维打印。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/070-p56.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-087"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-071", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "24 输出设备", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "071", "type": "选择题", "stem": "图像的打印精度单位是（   ）。", "options": {"A": "DPI", "B": "BPI", "C": "LPI", "D": "CPI"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，DPI（Dots Per Inch，每英寸点数）是衡量图像打印精度的单位，表示\n打印设备每英寸可以打印的点数。DPI 数值越高，打印精度越高，图像越清晰。\nA（DPI）正确，DPI 是打印精度的标准单位，常用于衡量打印机的分辨率，如 300 DPI、\n600 DPI、1200 DPI 等。\nB（BPI）错误，BPI（Bits Per Inch，每英寸位数）主要用于衡量磁盘存储密度，而非\n打印精度。\nC（LPI）错误，LPI（Lines Per Inch，每英寸线数）用于衡量网点印刷的网屏线数，\n适用于印刷行业，而非打印机精度。\nD（CPI）错误，CPI（Characters Per Inch，每英寸字符数）通常用于衡量打印机或\n打字机的字符间距，而非图像打印精度。\nB、C、D 都是专升本考试中不太可能考到的术语，所以专注于A（DPI）的概念即可。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/071-p56.jpg", "images/qb201/question-images/qfw800-ch3-v201/071-p57.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-088"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-072", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "25 主板", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "072", "type": "选择题", "stem": "在微型计算机中，主板有着重要的作用，它是其它部件和各种外部设备的（   ）。", "options": {"A": "连接载体", "B": "通信主体", "C": "访问桥梁", "D": "控制中心"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，主板（Motherboard）是微型计算机的核心部件之一，它提供了各个硬\n件部件（如 CPU、内存、硬盘、显卡等）以及外部设备（如鼠标、键盘、打印机等）\n的连接载体。主板上集成了数据总线、芯片组、接口等，确保计算机各个组件之间的互\n连和数据传输。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/072-p57.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-089"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-073", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "25 主板", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "073", "type": "选择题", "stem": "关于主板上的PCH 芯片组，以下说法错误的是（   ）。", "options": {"A": "PCH芯片组主要负责USB接口、I/O接口、SATA接口等的控制", "B": "PCH芯片组位于主板上离CPU插槽较远的位置", "C": "PCH芯片组是主板上的一个非必要组件，可以被其他芯片替代", "D": "PCH芯片组负责高级能源管理"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "芯片组是系统主板的灵魂，它决定了主板的结构及CPU 的使用。根据考纲书，PCH\n（Platform Controller Hub，平台控制器集线器）是现代主板上负责管理I/O 接口、\nUSB、SATA、PCIe、音频、网络等功能的重要芯片组。PCH 取代了传统的北桥和南\n桥架构，并与 CPU 协同工作，因此是主板上不可或缺的组件。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/073-p57.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-090"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-074", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "25 主板", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "074", "type": "选择题", "stem": "固化在计算机主板上的基本输入/输出系统简写是（   ）。", "options": {"A": "HDMI", "B": "BIOS", "C": "SATA", "D": "QPI"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，BIOS（Basic Input/Output System，基本输入/输出系统）是固化在计\n算机主板上的固件，负责计算机的基本硬件初始化和引导操作系统。BIOS 存储在主板\n上的ROM（只读存储器）**或 Flash 存储芯片中，是计算机启动过程中最先运行的软\n件。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/074-p58.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-091"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-075", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "25 主板", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "075", "type": "填空题", "stem": "微型计算机的启动过程如下图所示，其中空白处应该填写的是_____。", "options": {}, "verifiedAnswer": "加载操作系统", "sourceAnswer": "加载操作系统", "analysis": "根据考纲书，微型计算机的启动过程通常包括以下步骤：\n① 开机：计算机通电启动。\n② 自检（POST，自检程序）：BIOS 进行基本硬件检测，确保各部件正常工作。\n③ 执行 ROM 中的启动程序：BIOS 读取存储在 ROM（只读存储器）中的引导程序，\n并执行它。\n④ 加载操作系统：引导程序从硬盘或其他存储设备中加载操作系统到内存中。\n⑤ 执行操作系统：操作系统完成初始化，用户可以使用计算机。\n从图示来看，空白处应该填写的是“加载操作系统”，因为该步骤是 BIOS 完成硬件\n自检后，引导计算机进入操作系统的关键过程。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/075-p58.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw800-ch3-v201/075-p58.jpg"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-076", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "076", "type": "选择题", "stem": "关于总线的概念，下列说法错误的是（   ）。", "options": {"A": "总线是计算机系统中各部件之间传输数据的公用通道", "B": "总线的带宽是共享的，连接的设备越多，每个设备的有效传输速率越低", "C": "总线可以采用点对点传输方式，每个设备独享带宽", "D": "总线仅用于CPU内部各部件之间的数据传输"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，总线是计算机系统中各部件之间传输数据的公用通道，用于连接 CPU、\n内存、输入/输出设备等，实现数据、地址和控制信息的传输。\n总线不仅用于 CPU 内部，还用于CPU 与内存、存储设备、I/O 设备等之间的数据通\n信，因此不局限于 CPU 内部。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/076-p58.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-095"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-077", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "077", "type": "填空题", "stem": "按传输方式分类，计算机的总线分为串行总线和并行总线。其中，USB 属于_____总 线。", "options": {}, "verifiedAnswer": "串行", "sourceAnswer": "串行", "analysis": "根据考纲书中关于总线分类的内容，按数据传输方式可将总线分为：\n① 串行总线 - 数据按位依次传输；\n② 并行总线 - 数据多位同时传输。\nUSB（Universal Serial Bus，通用串行总线）从名称即可看出，其本身就是“通用串\n行总线”，属于串行总线的一种。USB 通过串行方式逐位传输数据，因此归类为串行总\n线。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/077-p59.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-078", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "078", "type": "判断题", "stem": "在串行总线中，二进制数逐位通过一根数据线发送到目的部件，因此传输控制比较简单， 数据传输的频率较高。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，串行总线（Serial Bus）是一种数据传输方式，它通过单条数据线逐位传\n输二进制数据。由于串行传输的线路较少，减少了信号干扰和复杂的同步控制，因此传\n输控制较简单。此外，现代串行总线（如 USB、PCIe、SATA 等）采用高速串行通信\n技术，能够支持较高的数据传输频率，甚至超过传统的并行总线。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/078-p59.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-096"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-079", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "079", "type": "选择题", "stem": "下列关于总线带宽的说法中，不正确的是（   ）。", "options": {"A": "工作频率越高，总线的物理长度越长", "B": "单位时间内传输次数越多带宽越高", "C": "总线工作频率越高带宽越高", "D": "总线位宽越多带宽越高"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，总线带宽指的是单位时间内总线所能传输的数据量，其计算公式为：\n总线带宽 = 单位时间内传输次数 × 数据传输率 × 位宽\n影响总线带宽的主要因素包括：\n单位时间内传输次数：除了全双工（即发送的同时可以接收）的单位传输次数为2 之\n外，其它的传输方式，该值都固定为1。\n总线工作频率：频率越高，每秒传输的数据次数越多，带宽越高。\n总线位宽：总线一次能传输的数据位数越多，带宽越高。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/079-p59.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-097"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-080", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "080", "type": "判断题", "stem": "总线带宽是指总线能够同时传输的二进制位数。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "总线能够同时传输的二进制位数称为总线位宽，而总线带宽 = 单位时间内传输次数\n× 数据传输率 × 位宽，因此题干的说法是错误的。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/080-p59.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-098"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-081", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "081", "type": "填空题", "stem": "计算机总线的工作频率为33MHz，总线的宽度为64bit，则它的传输速率为_____MB/s。", "options": {}, "verifiedAnswer": "264", "sourceAnswer": "264", "analysis": "总线带宽 = 单位时间内传输次数 × 数据传输率 × 位宽\n因此，总线带宽 = 1 × 33 MHz × 64 bit ÷ 8 = 264 MB/s。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/081-p60.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-082", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "082", "type": "填空题", "stem": "USB 接口是一种通用的_____（串行/并行）总线接口，支持即插即用和热插拔。", "options": {}, "verifiedAnswer": "串行", "sourceAnswer": "串行", "analysis": "根据考纲书，USB（Universal Serial Bus，通用串行总线）是一种串行总线接口，用\n于连接计算机与外部设备。USB 采用串行数据传输方式，相较于传统的并行接口（如\n并口打印机接口），它具有更高的传输效率，并支持即插即用和热插拔功能，广泛用于\n键盘、鼠标、U 盘、移动硬盘等设备的连接。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/082-p60.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-083", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "083", "type": "填空题", "stem": "如下图所示的连接符号是_____。", "options": {}, "verifiedAnswer": "USB", "sourceAnswer": "USB", "analysis": "记住结论即可。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/083-p60.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw800-ch3-v201/083-p60.jpg"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-084", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "084", "type": "选择题", "stem": "高清晰度的多媒体接口是（   ）。", "options": {"A": "USB", "B": "VGA", "C": "RJ-45", "D": "HDMI"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，HDMI（High-Definition Multimedia Interface，高清多媒体接口）是\n一种用于传输高清视频和音频的数字接口，广泛应用于电视、显示器、投影仪和游戏机\n等设备。HDMI 具备高清晰度、无压缩、支持音视频同步传输的特点，是当前主流的\n多媒体接口。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/084-p60.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-104"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-085", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "085", "type": "选择题", "stem": "下列表示高清晰度多媒体接口的是（   ）。", "options": {"A": "图A", "B": "图B", "C": "图C", "D": "图D"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "A（HDMI），即标准的高清晰度多媒体接口，支持音视频同步传输。\nB（Ethernet），即以太网的RJ-45 接口，用于网络通信。\nC（SATA），即串行 ATA，是硬盘和主板之间的数据传输接口。\nD（DVI），即数字视频接口，仅支持视频信号传输，不支持音频，因此不能完全满足高\n清多媒体需求。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/085-p60.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw800-ch3-v201/085-p60.jpg"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-086", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "086", "type": "选择题", "stem": "下列不属于微型计算机接口的是（   ）。", "options": {"A": "RJ-45", "B": "HDMI", "C": "ADSL", "D": "USB"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，微型计算机接口是用于连接计算机与其他设备的硬件接口，如网络接口、\n显示接口、数据传输接口等。\nA（RJ-45），RJ-45 是计算机网络接口，用于以太网连接（LAN）。\nB（HDMI），HDMI 是高清多媒体接口，用于连接显示设备。\nC（ADSL），ADSL（Asymmetric Digital Subscriber Line，非对称数字用户线路）\n是一种宽带接入技术，用于连接互联网，而不是计算机的标准接口。\nD（USB），USB（Universal Serial Bus）是通用串行总线接口，广泛用于数据传输和\n外设连接。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/086-p61.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-106"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-087", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "087", "type": "判断题", "stem": "SATA 接口是一种高速的串行接口，用于硬盘和内存之间的数据传输。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，SATA（Serial ATA，串行高级技术附件）是一种高速串行接口，主要用\n于计算机主板与硬盘（HDD、SSD）、光驱等存储设备之间的数据传输。相比于早期的\n并行 ATA（PATA）接口，SATA 具有传输速率更高、数据线更细、支持热插拔等优点。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/087-p61.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-107"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-088", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "088", "type": "填空题", "stem": "根据总线上传输信号的不同，可将总线分为地址总线、数据总线和_____。", "options": {}, "verifiedAnswer": "控制总线", "sourceAnswer": "控制总线", "analysis": "根据考纲书，计算机的总线按传输的信号类型可以分为三类：\n① 地址总线（Address Bus）：用于传输内存地址或 I/O 设备地址。地址总线的位宽\n决定了CPU 的最大寻址空间。例如，32 位的地址线，最大寻址空间为 2³² 字节，即 4 GB。\n② 数据总线（Data Bus）：用于传输计算机内部的实际数据。数据总线的位宽一般等于\nCPU 的字长，即CPU 一次能处理的二进制数的最大位数。\n③ 控制总线（Control Bus）：用于传输控制信号，以协调 CPU、内存和 I/O 设备的\n工作。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/088-p61.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-089", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "089", "type": "填空题", "stem": "计算机地址总线的位数决定了计算机的寻址范围，若地址总线的位数为32 位，则寻址 空间为_____GB。", "options": {}, "verifiedAnswer": "4", "sourceAnswer": "4", "analysis": "根据计算机组成原理，地址总线的位数决定了可寻址的存储单元个数。\n若地址总线为 n 位，则可寻址单元数 =ʹ௡\n本题中，地址总线位数为 32 位：可寻址单元数 = ʹଷଶ 个存储单元\n由于计算机按字节编址（一个地址对应 1 字节），因此：\nʹଷଶ 字节 = Ͷ ൈʹଷ଴ 字节，而：1 GB = ʹଷ଴ 字节\n所以： ʹଷଶ 字节 = Ͷ ൈʹଷ଴ = 4 GB", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/089-p62.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-090", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "26 总线", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "090", "type": "选择题", "stem": "关于计算机总线的叙述错误的是（   ）。", "options": {"A": "总线是计算机各个部件之间进行信息传递的公共通道", "B": "微型计算机的各个部件通过主板和总线连接形成一个整体", "C": "根据总线中流动的信息不同，分为地址总线、数据总线和控制总线", "D": "数据总线是单向的，地址总线是双向的"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书中关于计算机总线的内容：\n① 总线是计算机各部件之间进行信息传递的公共通道。\n② 微型计算机的各个部件通过主板和总线连接形成一个整体。主板是各部件连接的平\n台，总线负责信息传输。\n③ 根据总线中传输信息的不同，总线分为地址总线、数据总线和控制总线。\n④ 数据总线是双向的，因为 CPU 既可以向存储器或 I/O 设备发送数据，也可以从它\n们接收数据；地址总线通常是单向的，由 CPU 向外部设备发送地址信息。\nD 选项“数据总线是单向的，地址总线是双向的”，恰好与实际情况相反。\n因此，答案为 D。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/090-p62.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-091", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "27 软件基础", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "091", "type": "填空题", "stem": "软件系统分为_____软件和_____软件。", "options": {}, "verifiedAnswer": "系统，应用", "sourceAnswer": "系统，应用", "analysis": "根据考纲书，软件系统通常分为两大类：\n系统软件：用于管理计算机硬件资源并为应用软件提供运行环境，例如操作系统\n（Windows、Linux）、驱动程序、编译器等。\n应用软件：用于满足用户特定需求的程序，例如办公软件（Word、Excel）、浏览器、\n游戏、图像处理软件等。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/091-p62.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-092", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "27 软件基础", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "092", "type": "选择题", "stem": "实用程序完成一些与管理计算机系统资源及文件有关的任务，（   ）不属于实用程序。", "options": {"A": "Windows", "B": "Windows优化大师", "C": "备份程序", "D": "WinRAR压缩软件"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，实用程序（Utility Programs）是系统软件的一种，主要用于管理计算机\n资源、优化系统性能、文件管理和数据备份等。例如：磁盘清理工具、压缩软件、杀毒\n软件、备份工具等。\nA（Windows）是操作系统，属于系统软件，而不是专门的实用程序。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/092-p63.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-118"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-093", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "27 软件基础", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "093", "type": "选择题", "stem": "下列各组软件中，全部属于应用软件的是（   ）。", "options": {"A": "程序语言处理程序、操作系统、数据库管理系统", "B": "文字处理程序、编辑程序、UNIX", "C": "视频播放软件、图像处理软件、Windows 10", "D": "财务处理软件、金融软件、办公自动化软件"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "根据考纲书，应用软件是用于满足用户特定需求的软件，例如办公软件、财务软件、多\n媒体软件等，而系统软件则用于管理计算机资源并提供基本运行环境。\nA 选项中的操作系统、B 选项中的UNIX 和C 选项中Windows 10 都是系统软件，不\n属于应用软件的范畴。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/093-p63.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-119"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-094", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "094", "type": "填空题", "stem": "用_____编写的程序计算机能直接识别。", "options": {}, "verifiedAnswer": "机器语言", "sourceAnswer": "机器语言", "analysis": "根据考纲书，计算机只能直接识别和执行机器语言编写的程序。机器语言由二进制代码\n（0 和 1）组成，每条指令对应计算机硬件可以直接执行的操作。相比于高级语言（如\nC、Java）和汇编语言，机器语言不需要翻译，可以被计算机的 CPU 直接识别并执行。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/094-p63.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-095", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "095", "type": "选择题", "stem": "对于汇编语言的评述中，（   ）是不正确的。", "options": {"A": "汇编语言有编译型和解释型", "B": "汇编语言采用助记符来代替机器语言中的指令和数据，又称为符号语言", "C": "机器语言、汇编语言和高级语言是计算机语言发展的3个阶段", "D": "汇编语言运行速度快，适用编制实时控制应用程序"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据计算机语言的发展过程，计算机语言一般经历了三个阶段：\n① 机器语言  ② 汇编语言  ③ 高级语言\n因此，C 选项“机器语言、汇编语言和高级语言是计算机语言发展的3 个阶段”表述正\n确。\n关于汇编语言的特点：\n汇编语言采用助记符（如 MOV、ADD 等）来代替机器指令的操作码，是面向机器的\n符号语言，因此 B 正确。\n汇编语言生成的目标代码接近机器语言，执行效率高，占用资源少，因此常用于实时控\n制系统或对速度要求较高的场合，D 正确。\nA、汇编语言有编译型和解释型，则是错误的。  汇编语言必须通过“汇编程序”将其\n翻译成机器语言后才能执行，它不区分编译型和解释型。“编译型和解释型”通常是针\n对高级语言而言的分类，而不适用于汇编语言。\n因此，答案为 A。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/095-p63.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-096", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "096", "type": "判断题", "stem": "机器语言和汇编语言编写的程序的运行效率低于高级语言，所以机器语言和汇编语言称 为低级语言。（   ）", "options": {"A": "对", "B": "错"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，机器语言和汇编语言属于低级语言，但它们的运行效率并不低于高级语言，\n反而通常比高级语言更高效。机器语言和汇编语言之所以称为低级语言，是因为它们是\n面向机器的，距离人类的自然语言更远。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/096-p64.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-121"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-097", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "097", "type": "填空题", "stem": "下图中①处应填写_____。", "options": {}, "verifiedAnswer": "汇编程序", "sourceAnswer": "汇编程序", "analysis": "根据考纲书，汇编语言源程序需要经过汇编程序的翻译，才能转换为机器语言程序，供\n计算机直接执行。\n图中①的作用是将汇编语言转换为机器语言，这一过程由汇编程序完成。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/097-p64.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw800-ch3-v201/097-p64.jpg"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-098", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "098", "type": "选择题", "stem": "用高级语言编写的程序称为（   ）。", "options": {"A": "源程序", "B": "编译程序", "C": "可执行程序", "D": "编辑程序"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，用高级语言编写的程序称为源程序，它需要经过编译器或解释器转换为计\n算机可以执行的机器语言程序。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/098-p64.jpg"], "firstStatus": "未作答", "canonicalId": "CQZSB-COMP-20261014-196"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-099", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "099", "type": "填空题", "stem": "计算机高级程序设计语言翻译为机器语言的方式有编译方式和_____方式。", "options": {}, "verifiedAnswer": "解释", "sourceAnswer": "解释", "analysis": "根据考纲书中关于高级程序设计语言的说明，高级语言程序必须经过翻译才能被计算机\n执行，其翻译方式有两种：\n① 编译方式：通过编译程序一次性将源程序翻译成目标程序（机器语言程序），然后执\n行目标程序；\n② 解释方式：通过解释程序对源程序逐条翻译、逐条执行，不生成独立的目标程序。\n因此，计算机高级程序设计语言翻译为机器语言的方式有编译方式和解释方式。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/099-p65.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-100", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "100", "type": "选择题", "stem": "解释程序和编译程序在处理源程序时的主要区别是（   ）。", "options": {"A": "解释程序逐句执行源程序，编译程序整体编译源程序", "B": "解释程序适用于高级语言，编译程序适用于汇编语言", "C": "解释程序生成目标程序，编译程序不生成目标程序", "D": "解释程序执行速度通常比编译程序快"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，解释程序和编译程序在处理源程序时的主要区别如下：\n解释程序：逐行翻译并立即执行源程序，不生成独立的可执行文件。例如 Python、\nJavaScript 采用解释执行。\n编译程序：一次性将整个源程序翻译成机器代码（目标程序），然后执行，生成独立的\n可执行文件。例如 C、C++ 采用编译执行。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/100-p65.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-130"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-101", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "101", "type": "填空题", "stem": "下图中①处应填写_____。", "options": {}, "verifiedAnswer": "解释程序", "sourceAnswer": "解释程序", "analysis": "根据考纲书，图示流程表示高级语言源程序直接执行，并产生计算结果，这符合解释程\n序（Interpreter）的工作方式。\n解释程序的特点：\n① 逐行翻译并立即执行，不会生成目标程序和可执行文件。\n② 适用于 Python、JavaScript、BASIC 等语言。\n③ 每次运行时都需要解释器，因此执行速度通常比编译程序慢。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/101-p65.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw800-ch3-v201/101-p65.jpg"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-102", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "102", "type": "选择题", "stem": "下图中①和②处应填写（   ）。", "options": {"A": "解释程序，编译程序", "B": "编译程序、解释程序", "C": "编译程序，连接程序", "D": "连接程序、编译程序"}, "verifiedAnswer": "C", "sourceAnswer": "C", "analysis": "根据考纲书，该图示表示 C 语言程序的编译和执行过程，涉及两个关键步骤：\n源程序（.c）→ 目标程序（.obj）\n① 由编译程序完成，将高级语言转换为机器语言的目标文件（.obj）；\n② 目标程序（.obj）→ 可执行程序（.exe）\n由连接程序完成，它负责将多个目标文件（如 .obj 文件）与库文件链接生成最终的可\n执行程序（.exe）。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/102-p66.jpg"], "firstStatus": "未作答", "stemImage": "images/qb201/question-images/qfw800-ch3-v201/102-p66.jpg"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-103", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "103", "type": "选择题", "stem": "下面（   ）语言是解释型语言。", "options": {"A": "Fortran", "B": "C语言", "C": "Pascal", "D": "Basic"}, "verifiedAnswer": "D", "sourceAnswer": "D", "analysis": "Fortran、Pascal 和C 语言都是编译型的语言，而Basic 语言主要使用解释方式。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/103-p66.jpg"], "firstStatus": "未作答"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-104", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "104", "type": "选择题", "stem": "以下程序设计语言中，采用虚拟机技术，因而具有良好跨平台特性的是（   ）。", "options": {"A": "Java", "B": "C++", "C": "C#", "D": "VB"}, "verifiedAnswer": "A", "sourceAnswer": "A", "analysis": "根据考纲书，Java 语言采用Java 虚拟机（JVM，Java Virtual Machine）技术，使\n其具备良好的跨平台特性。Java 源代码首先被编译为字节码，然后由 JVM 在不同操\n作系统上解释执行，做到“一次编写，到处运行”。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/104-p66.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-135"}, {"id": "QFW-26-LAST800-COMPUTER-CH03-105", "subject": "计算机", "bookCode": "1.4", "topic": "计算机系统组成", "point": "28 程序设计语言", "sourceChapter": "第3章 计算机系统组成", "source": "全方位 · 26集训最后800题", "batch": "26集训最后800题", "sourceNo": "105", "type": "选择题", "stem": "Python 是一种面向对象的（   ）。", "options": {"A": "编译型语言", "B": "解释型语言", "C": "汇编型语言", "D": "非结构化语言"}, "verifiedAnswer": "B", "sourceAnswer": "B", "analysis": "根据考纲书，Python 是一种面向对象的解释型语言，其代码逐行解释执行，不需要编\n译成二进制机器码。Python 代码由 Python 解释器直接运行，适用于快速开发、数\n据分析、人工智能等领域。", "sourceImageRefs": ["images/qb201/question-images/qfw800-ch3-v201/105-p67.jpg"], "firstStatus": "未作答", "canonicalId": "QFW-20260821-COMP-CH3-137"}]);
